INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'wancha'), 'From Six to Ten', 'A day in my life', 'A1', '{"title":"From Six to Ten","summary_vi":"Bạn sẽ luyện kể về một ngày bình thường từ sáng đến tối.","sentences":["I get up at six o''clock.","I brush my teeth and take a shower.","Then I eat breakfast with my mother.","I go to school by bus.","Classes start at eight.","After school, I do my homework.","In the evening, I watch TV.","I go to bed at ten."],"sentences_vi":["Mình thức dậy lúc sáu giờ.","Mình đánh răng và đi tắm.","Sau đó mình ăn sáng với mẹ.","Mình đi học bằng xe buýt.","Tiết học bắt đầu lúc tám giờ.","Tan học, mình làm bài tập về nhà.","Buổi tối, mình xem ti vi.","Mình đi ngủ lúc mười giờ."],"vocabulary":[{"word":"get up","ipa":"/ɡet ʌp/","pos":"phrase","meaning_vi":"thức dậy","example":"I get up early on Monday.","example_vi":"Thứ Hai mình dậy sớm."},{"word":"take a shower","ipa":"/teɪk ə ˈʃaʊər/","pos":"phrase","meaning_vi":"tắm vòi sen","example":"Please take a shower before dinner.","example_vi":"Làm ơn đi tắm trước bữa tối nhé."},{"word":"breakfast","ipa":"/ˈbrekfəst/","pos":"noun","meaning_vi":"bữa sáng","example":"Breakfast is my favorite meal.","example_vi":"Bữa sáng là bữa ăn mình thích nhất."},{"word":"school","ipa":"/skuːl/","pos":"noun","meaning_vi":"trường học","example":"Her school is very big.","example_vi":"Trường của cô ấy rất lớn."},{"word":"by bus","ipa":"/baɪ bʌs/","pos":"phrase","meaning_vi":"bằng xe buýt","example":"My uncle goes to work by bus.","example_vi":"Chú mình đi làm bằng xe buýt."},{"word":"homework","ipa":"/ˈhoʊmwɜːrk/","pos":"noun","meaning_vi":"bài tập về nhà","example":"I finish my homework at home.","example_vi":"Mình làm xong bài tập ở nhà."},{"word":"evening","ipa":"/ˈiːvnɪŋ/","pos":"noun","meaning_vi":"buổi tối","example":"We walk in the park in the evening.","example_vi":"Buổi tối chúng mình đi dạo trong công viên."},{"word":"go to bed","ipa":"/ɡoʊ tuː bed/","pos":"phrase","meaning_vi":"đi ngủ","example":"The children go to bed at nine.","example_vi":"Bọn trẻ đi ngủ lúc chín giờ."}],"questions":[{"question":"What time does the speaker get up?","options":["At five","At seven","At eight","At six"],"answer_index":3,"explanation_vi":"Người nói thức dậy lúc sáu giờ."},{"question":"How does the speaker go to school?","options":["By bus","By bike","On foot","By car"],"answer_index":0,"explanation_vi":"Câu chuyện nói: I go to school by bus."},{"question":"What does the speaker do after school?","options":["Plays football","Watches TV","Does homework","Goes to bed"],"answer_index":2,"explanation_vi":"Sau giờ học, người nói làm bài tập về nhà."},{"question":"When does the speaker go to bed?","options":["At nine","At ten","At eleven","At midnight"],"answer_index":1,"explanation_vi":"Người nói đi ngủ lúc mười giờ."}]}', 'course', 1, 'a1-my-day', 'daily', 3)
