INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'wancha'), 'Coffee and Cake in Da Nang', 'Ordering at a café', 'A1', '{"title":"Coffee and Cake in Da Nang","summary_vi":"Bạn sẽ luyện gọi đồ uống, đồ ăn và thanh toán ở quán cà phê.","sentences":["Minh and Anna are in a café in Da Nang.","A waiter comes to their table.","Anna asks for a cup of tea.","Minh wants a coffee with milk.","He also orders a chocolate cake.","The cake is small, but it looks delicious.","They pay at the counter.","The bill is eighty thousand dong."],"sentences_vi":["Minh và Anna đang ở trong một quán cà phê ở Da Nang.","Một anh phục vụ đi đến bàn của họ.","Anna gọi một tách trà.","Minh muốn một ly cà phê sữa.","Anh ấy còn gọi thêm một chiếc bánh sô cô la.","Chiếc bánh nhỏ nhưng trông rất ngon.","Họ thanh toán ở quầy.","Hóa đơn là tám mươi nghìn đồng."],"vocabulary":[{"word":"waiter","ipa":"/ˈweɪtər/","pos":"noun","meaning_vi":"người phục vụ nam","example":"The waiter brings the menu.","example_vi":"Anh phục vụ mang thực đơn đến."},{"word":"table","ipa":"/ˈteɪbl/","pos":"noun","meaning_vi":"cái bàn","example":"We sit at a table by the window.","example_vi":"Chúng mình ngồi ở bàn cạnh cửa sổ."},{"word":"a cup of tea","ipa":"/ə kʌp əv tiː/","pos":"phrase","meaning_vi":"một tách trà","example":"I drink a cup of tea in the morning.","example_vi":"Buổi sáng mình uống một tách trà."},{"word":"coffee","ipa":"/ˈkɔːfi/","pos":"noun","meaning_vi":"cà phê","example":"This coffee is hot and strong.","example_vi":"Ly cà phê này nóng và đậm."},{"word":"orders","ipa":"/ˈɔːrdərz/","pos":"verb","meaning_vi":"gọi món","example":"My friend orders a sandwich for lunch.","example_vi":"Bạn mình gọi một cái bánh mì kẹp cho bữa trưa."},{"word":"delicious","ipa":"/dɪˈlɪʃəs/","pos":"adjective","meaning_vi":"ngon","example":"Your noodle soup is delicious.","example_vi":"Món mì nước của bạn ngon quá."},{"word":"pay","ipa":"/peɪ/","pos":"verb","meaning_vi":"trả tiền","example":"I pay with cash today.","example_vi":"Hôm nay mình trả bằng tiền mặt."},{"word":"bill","ipa":"/bɪl/","pos":"noun","meaning_vi":"hóa đơn","example":"Can we have the bill, please?","example_vi":"Cho chúng tôi xin hóa đơn nhé?"}],"questions":[{"question":"Where are Minh and Anna?","options":["In a café in Hanoi","In a restaurant in Hoi An","At home","In a café in Da Nang"],"answer_index":3,"explanation_vi":"Minh và Anna đang ở một quán cà phê tại Da Nang."},{"question":"What does Anna want to drink?","options":["Coffee with milk","A cup of tea","Orange juice","Water"],"answer_index":1,"explanation_vi":"Anna xin một tách trà."},{"question":"What does Minh order to eat?","options":["A sandwich","Ice cream","A chocolate cake","Noodle soup"],"answer_index":2,"explanation_vi":"Minh gọi thêm một chiếc bánh sô-cô-la."},{"question":"Where do they pay?","options":["At the counter","At the table","At the door","On the phone"],"answer_index":0,"explanation_vi":"Họ trả tiền ở quầy."}]}', 'course', 1, 'a1-at-the-cafe', 'food', 4)
