INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'wancha'), 'Postcard from Hoi An', 'The weather today', 'A1', '{"title":"Postcard from Hoi An","summary_vi":"Bạn sẽ luyện nói về thời tiết qua một tấm bưu thiếp từ Hội An.","sentences":["Hi Mai, greetings from Hoi An!","Today the weather is hot and sunny.","The sky is blue and there are no clouds.","I am wearing a hat and shorts.","In the evening, it is a little cool.","Now I am walking on the beach.","The water is warm.","I miss you!"],"sentences_vi":["Chào Mai, Hội An gửi lời chào đến bạn nhé!","Hôm nay trời nóng và nắng.","Bầu trời xanh và không có một gợn mây.","Mình đang đội mũ và mặc quần short.","Buổi tối trời hơi mát.","Bây giờ mình đang đi dạo trên bãi biển.","Nước biển ấm.","Mình nhớ bạn lắm!"],"vocabulary":[{"word":"weather","ipa":"/ˈweðər/","pos":"noun","meaning_vi":"thời tiết","example":"The weather is nice in spring.","example_vi":"Thời tiết mùa xuân thật đẹp."},{"word":"hot","ipa":"/hɑːt/","pos":"adjective","meaning_vi":"nóng","example":"The soup is too hot.","example_vi":"Món súp nóng quá."},{"word":"sunny","ipa":"/ˈsʌni/","pos":"adjective","meaning_vi":"có nắng","example":"It is a sunny day in Da Nang.","example_vi":"Hôm nay ở Da Nang là một ngày nắng."},{"word":"sky","ipa":"/skaɪ/","pos":"noun","meaning_vi":"bầu trời","example":"The sky is full of stars tonight.","example_vi":"Tối nay bầu trời đầy sao."},{"word":"clouds","ipa":"/klaʊdz/","pos":"noun","meaning_vi":"những đám mây","example":"Dark clouds are coming from the east.","example_vi":"Mây đen đang kéo đến từ phía đông."},{"word":"cool","ipa":"/kuːl/","pos":"adjective","meaning_vi":"mát mẻ","example":"The air is cool in the mountains.","example_vi":"Không khí ở vùng núi rất mát."},{"word":"beach","ipa":"/biːtʃ/","pos":"noun","meaning_vi":"bãi biển","example":"We play volleyball on the beach.","example_vi":"Chúng mình chơi bóng chuyền trên bãi biển."},{"word":"warm","ipa":"/wɔːrm/","pos":"adjective","meaning_vi":"ấm","example":"I want a warm drink.","example_vi":"Mình muốn một thức uống ấm."}],"questions":[{"question":"Where is the writer?","options":["In Hanoi","In Hoi An","In Da Nang","In London"],"answer_index":1,"explanation_vi":"Bưu thiếp gửi từ Hoi An."},{"question":"What is the weather like today?","options":["Cold and rainy","Cloudy and windy","Hot and sunny","Cool and foggy"],"answer_index":2,"explanation_vi":"Hôm nay trời nóng và có nắng."},{"question":"What is the writer wearing?","options":["A hat and shorts","A coat and boots","A jacket","A raincoat"],"answer_index":0,"explanation_vi":"Người viết đội mũ và mặc quần short."},{"question":"How is the water at the beach?","options":["Cold","Dirty","Very deep","Warm"],"answer_index":3,"explanation_vi":"Nước biển ấm."}]}', 'course', 1, 'a1-weather', 'nature', 6)
