  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'wancha'), 'Football and Grandma''s Soup', 'My weekend', 'A1', '{"title":"Football and Grandma''s Soup","summary_vi":"Bạn sẽ luyện kể về những hoạt động vui vẻ vào cuối tuần.","sentences":["On Saturday, I sleep late.","Then I play football with my friends.","In the afternoon, we eat ice cream.","On Sunday, I visit my grandmother.","She cooks my favorite soup.","After lunch, we watch a movie together.","I really love the weekend."],"sentences_vi":["Thứ Bảy mình ngủ nướng.","Sau đó mình chơi bóng đá với bạn bè.","Buổi chiều, chúng mình ăn kem.","Chủ nhật, mình đến thăm bà.","Bà nấu món súp mình thích nhất.","Sau bữa trưa, cả nhà cùng xem phim.","Mình thực sự yêu cuối tuần."],"vocabulary":[{"word":"Saturday","ipa":"/ˈsætərdeɪ/","pos":"noun","meaning_vi":"thứ Bảy","example":"We go to the zoo on Saturday.","example_vi":"Thứ Bảy chúng mình đi sở thú."},{"word":"sleep late","ipa":"/sliːp leɪt/","pos":"phrase","meaning_vi":"ngủ muộn","example":"My dad likes to sleep late on Sunday.","example_vi":"Bố mình thích ngủ nướng vào Chủ nhật."},{"word":"football","ipa":"/ˈfʊtbɔːl/","pos":"noun","meaning_vi":"bóng đá","example":"Football is popular in Vietnam.","example_vi":"Bóng đá rất phổ biến ở Việt Nam."},{"word":"ice cream","ipa":"/ˈaɪs kriːm/","pos":"noun","meaning_vi":"kem","example":"I want chocolate ice cream.","example_vi":"Mình muốn ăn kem sô cô la."},{"word":"visit","ipa":"/ˈvɪzɪt/","pos":"verb","meaning_vi":"thăm","example":"We visit our cousins in July.","example_vi":"Tháng Bảy chúng mình đến thăm các anh chị em họ."},{"word":"grandmother","ipa":"/ˈɡrænmʌðər/","pos":"noun","meaning_vi":"bà","example":"My grandmother lives in the countryside.","example_vi":"Bà mình sống ở quê."},{"word":"movie","ipa":"/ˈmuːvi/","pos":"noun","meaning_vi":"bộ phim","example":"That movie is very funny.","example_vi":"Bộ phim đó vui lắm."},{"word":"weekend","ipa":"/ˈwiːkend/","pos":"noun","meaning_vi":"cuối tuần","example":"Do you work at the weekend?","example_vi":"Bạn có đi làm vào cuối tuần không?"}],"questions":[{"question":"What does the speaker do on Saturday morning?","options":["Plays football","Visits grandmother","Sleeps late","Watches a movie"],"answer_index":2,"explanation_vi":"Sáng thứ Bảy người nói ngủ muộn."},{"question":"What do they eat in the afternoon?","options":["Soup","Ice cream","Cake","Fruit"],"answer_index":1,"explanation_vi":"Buổi chiều họ ăn kem."},{"question":"Who does the speaker visit on Sunday?","options":["His grandmother","His teacher","His uncle","His friends"],"answer_index":0,"explanation_vi":"Chủ nhật người nói thăm bà."},{"question":"What do they do after lunch?","options":["Play football","Cook soup","Go to the beach","Watch a movie"],"answer_index":3,"explanation_vi":"Sau bữa trưa họ cùng xem phim."}]}', 'course', 1, 'a1-weekend', 'fun', 8)
