INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'wancha'), 'Tom''s Cheap Adventure', 'Travelling on a budget', 'B1', '{"title":"Tom''s Cheap Adventure","summary_vi":"Luyện nghe và đọc câu chuyện về chuyến du lịch Việt Nam tiết kiệm của một người bạn.","sentences":["Last summer, my friend Tom from Canada travelled around Vietnam on a tight budget.","He had saved up for six months, but he still had to be careful with money.","Instead of expensive hotels, he stayed in cheap hostels where he met other travellers.","In Hanoi, he joined a free walking tour and gave the guide a small tip.","He also learned that local buses are much cheaper than taxis.","When he got hungry, he ate where the locals ate, so every meal cost only a few dollars.","Tom booked his flights well in advance, which saved him a lot of money.","Of course, not everything went smoothly, because his bus broke down near Hue.","He waited for three hours, but he made friends with a family who shared their snacks.","By the end of the trip, he had spent less than he expected.","He says that travelling cheaply makes you more creative and more open to surprises."],"sentences_vi":["Mùa hè năm ngoái, anh bạn Tom của tôi đến từ Canada đã đi du lịch khắp Việt Nam với ngân sách eo hẹp.","Anh ấy đã dành dụm suốt sáu tháng, nhưng vẫn phải cẩn thận với từng đồng tiền.","Thay vì ở khách sạn đắt tiền, anh ở các hostel giá rẻ, nơi anh gặp gỡ những du khách khác.","Ở Hanoi, anh tham gia một tour đi bộ miễn phí và boa cho hướng dẫn viên một khoản nhỏ.","Anh cũng nhận ra rằng xe buýt địa phương rẻ hơn taxi rất nhiều.","Khi đói, anh ăn ở nơi người dân địa phương ăn, nên mỗi bữa chỉ tốn vài đô la.","Tom đặt vé máy bay từ rất sớm, nhờ vậy tiết kiệm được khá nhiều tiền.","Dĩ nhiên, không phải chuyện gì cũng suôn sẻ, vì xe buýt của anh bị hỏng gần Hue.","Anh chờ ba tiếng đồng hồ, nhưng lại kết bạn được với một gia đình đã chia sẻ đồ ăn vặt cho anh.","Đến cuối chuyến đi, anh đã tiêu ít hơn dự tính.","Anh nói rằng đi du lịch tiết kiệm khiến bạn sáng tạo hơn và cởi mở hơn với những điều bất ngờ."],"vocabulary":[{"word":"on a tight budget","ipa":"/ɑːn ə taɪt ˈbʌdʒɪt/","pos":"phrase","meaning_vi":"với ngân sách eo hẹp","example":"Many students live on a tight budget in big cities.","example_vi":"Nhiều sinh viên sống với ngân sách eo hẹp ở các thành phố lớn."},{"word":"saved up","ipa":"/seɪvd ʌp/","pos":"phrasal verb","meaning_vi":"để dành tiền","example":"She saved up enough money to buy a new bike.","example_vi":"Cô ấy đã dành dụm đủ tiền để mua một chiếc xe đạp mới."},{"word":"walking tour","ipa":"/ˈwɔːkɪŋ tʊr/","pos":"noun","meaning_vi":"tour đi bộ","example":"A walking tour is a great way to see the old streets.","example_vi":"Đi bộ theo tour là một cách tuyệt vời để ngắm những con phố cổ."},{"word":"in advance","ipa":"/ɪn ədˈvæns/","pos":"phrase","meaning_vi":"trước, từ sớm","example":"You should reserve a table in advance on weekends.","example_vi":"Bạn nên đặt bàn trước vào cuối tuần."},{"word":"broke down","ipa":"/broʊk daʊn/","pos":"phrasal verb","meaning_vi":"bị hỏng","example":"Our car broke down on the highway last night.","example_vi":"Tối qua xe của chúng tôi bị hỏng trên đường cao tốc."},{"word":"made friends with","ipa":"/meɪd frendz wɪð/","pos":"phrase","meaning_vi":"kết bạn với","example":"On the first day of school, he made friends with his neighbour.","example_vi":"Ngày đầu đi học, cậu ấy đã kết bạn với người hàng xóm."},{"word":"open to","ipa":"/ˈoʊpən tuː/","pos":"adjective phrase","meaning_vi":"sẵn sàng đón nhận","example":"Good managers are open to new ideas.","example_vi":"Những người quản lý giỏi luôn cởi mở với các ý tưởng mới."}],"questions":[{"question":"How did Tom pay for his trip?","options":["His company paid for it","He borrowed from a friend","He won a prize","He had saved money for six months"],"answer_index":3,"explanation_vi":"Tom đã để dành tiền suốt sáu tháng."},{"question":"Why were his meals so cheap?","options":["He ate where local people ate","He cooked in the hostel","He skipped lunch","Hotels gave him free food"],"answer_index":0,"explanation_vi":"Anh ăn ở những quán người địa phương hay ăn."},{"question":"What went wrong near Hue?","options":["He lost his wallet","His bus broke down","His flight was cancelled","He missed the tour"],"answer_index":1,"explanation_vi":"Xe buýt của anh bị hỏng gần Huế."},{"question":"What does Tom think about cheap travel?","options":["It is boring and tiring","It is only for the young","It makes people more creative and open","It is too risky"],"answer_index":2,"explanation_vi":"Tom cho rằng đi tiết kiệm khiến ta sáng tạo và cởi mở hơn."}]}', 'course', 1, 'b1-budget-travel', 'travel', 19)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'wancha'), 'Finding Your Rhythm', 'Living in a big city', 'B1', '{"title":"Finding Your Rhythm","summary_vi":"Luyện nghe và nói về cách làm quen với cuộc sống ở một thành phố lớn.","sentences":["Moving to a big city can be exciting, but it takes time to get used to it.","When I first moved to Saigon, the traffic and the noise nearly drove me crazy.","My cousin Minh, who has lived here for ten years, gave me some advice.","He said I should find a quiet café or park where I can relax after work.","He also told me to learn the bus routes instead of relying on taxis.","Living in a city is expensive, so it helps to keep track of what you spend.","On the other hand, there are always things to do, from concerts to street markets.","If you feel lonely, join a club or a class to meet new people.","After six months, I have finally found my own rhythm.","I still miss my hometown, but I no longer want to leave."],"sentences_vi":["Chuyển đến một thành phố lớn có thể rất thú vị, nhưng cần thời gian để làm quen.","Khi mới chuyển đến Saigon, giao thông và tiếng ồn suýt làm tôi phát điên.","Anh họ tôi, Minh, đã sống ở đây mười năm, cho tôi vài lời khuyên.","Anh bảo tôi nên tìm một quán cà phê hay công viên yên tĩnh để thư giãn sau giờ làm.","Anh cũng bảo tôi hãy học các tuyến xe buýt thay vì phụ thuộc vào taxi.","Sống ở thành phố rất đắt đỏ, nên theo dõi các khoản chi tiêu sẽ có ích.","Mặt khác, lúc nào cũng có nhiều thứ để làm, từ các buổi hòa nhạc đến những khu chợ đường phố.","Nếu cảm thấy cô đơn, hãy tham gia một câu lạc bộ hoặc một lớp học để gặp gỡ người mới.","Sau sáu tháng, cuối cùng tôi đã tìm được nhịp sống của riêng mình.","Tôi vẫn nhớ quê nhà, nhưng tôi không còn muốn rời đi nữa."],"vocabulary":[{"word":"get used to","ipa":"/ɡet juːst tuː/","pos":"phrasal verb","meaning_vi":"làm quen với","example":"It took me a week to get used to the cold weather.","example_vi":"Tôi mất một tuần để quen với thời tiết lạnh."},{"word":"drove me crazy","ipa":"/droʊv miː ˈkreɪzi/","pos":"phrase","meaning_vi":"làm tôi phát điên","example":"The loud music next door drove me crazy last night.","example_vi":"Tiếng nhạc lớn nhà bên cạnh tối qua làm tôi phát điên."},{"word":"relying on","ipa":"/rɪˈlaɪɪŋ ɑːn/","pos":"phrasal verb","meaning_vi":"dựa vào","example":"He is relying on his parents to pay for university.","example_vi":"Cậu ấy đang trông cậy vào bố mẹ để trả tiền học đại học."},{"word":"keep track of","ipa":"/kiːp træk əv/","pos":"phrase","meaning_vi":"theo dõi, ghi nhớ","example":"I use an app to keep track of my homework.","example_vi":"Tôi dùng một ứng dụng để theo dõi bài tập về nhà."},{"word":"on the other hand","ipa":"/ɑːn ðə ˈʌðər hænd/","pos":"phrase","meaning_vi":"mặt khác","example":"The flat is small. On the other hand, it is very cheap.","example_vi":"Căn hộ nhỏ. Mặt khác, nó rất rẻ."},{"word":"rhythm","ipa":"/ˈrɪðəm/","pos":"noun","meaning_vi":"nhịp sống, nhịp điệu","example":"After the holiday, it was hard to get back into a work rhythm.","example_vi":"Sau kỳ nghỉ, thật khó để quay lại nhịp làm việc."}],"questions":[{"question":"What bothered the writer most at first in Saigon?","options":["The weather","The traffic and noise","The food","The neighbours"],"answer_index":1,"explanation_vi":"Giao thông và tiếng ồn suýt làm người viết phát điên."},{"question":"What advice did Minh give about transport?","options":["Buy a motorbike","Avoid going out","Rely on taxis","Learn the bus routes"],"answer_index":3,"explanation_vi":"Minh khuyên nên học các tuyến xe buýt thay vì dựa vào taxi."},{"question":"What should you do if you feel lonely?","options":["Join a club or a class","Move back home","Stay in a café","Call a taxi"],"answer_index":0,"explanation_vi":"Bài khuyên tham gia câu lạc bộ hoặc lớp học để gặp người mới."},{"question":"How does the writer feel after six months?","options":["Ready to leave the city","Angry about the cost","More settled, though still missing home","Bored with city events"],"answer_index":2,"explanation_vi":"Người viết đã quen nhịp sống nhưng vẫn nhớ quê."}]}', 'course', 1, 'b1-city-life', 'daily', 20)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'wancha'), 'Little by Little', 'Learning a new language', 'B1', '{"title":"Little by Little","summary_vi":"Luyện nghe và đọc về thói quen học ngoại ngữ mỗi ngày của một cô gái tên Linh.","sentences":["Linh has been learning English for three years, and her progress has surprised everyone.","She says the secret is to practise a little every day rather than a lot once a week.","Every morning, she listens to a short podcast while she walks to work.","Whenever she hears a new word, she writes it down and looks it up later.","She is not afraid of making mistakes, because she knows they help her learn.","Last year, she joined an online group where members chat with native speakers.","At first she felt shy, but her confidence has grown quickly.","If you want to speak fluently, you have to use the language in real situations.","Linh also watches films without subtitles to train her ears.","She believes that anyone can improve if they stay patient and keep going."],"sentences_vi":["Linh đã học tiếng Anh được ba năm, và sự tiến bộ của cô ấy khiến mọi người ngạc nhiên.","Cô nói bí quyết là luyện tập mỗi ngày một ít thay vì một tuần chỉ học một lần thật nhiều.","Mỗi buổi sáng, cô nghe một podcast ngắn trong lúc đi bộ đến chỗ làm.","Mỗi khi nghe được một từ mới, cô ghi lại và tra nghĩa sau.","Cô không sợ mắc lỗi, vì cô biết lỗi sai giúp mình học hỏi.","Năm ngoái, cô tham gia một nhóm trực tuyến, nơi các thành viên trò chuyện với người bản xứ.","Lúc đầu cô thấy ngại, nhưng sự tự tin của cô đã tăng lên nhanh chóng.","Nếu muốn nói trôi chảy, bạn phải dùng ngôn ngữ đó trong những tình huống thực tế.","Linh còn xem phim không phụ đề để rèn luyện đôi tai.","Cô tin rằng ai cũng có thể tiến bộ nếu kiên nhẫn và tiếp tục cố gắng."],"vocabulary":[{"word":"rather than","ipa":"/ˈræðər ðæn/","pos":"phrase","meaning_vi":"hơn là, thay vì","example":"I prefer tea rather than coffee in the evening.","example_vi":"Buổi tối tôi thích trà hơn cà phê."},{"word":"writes it down","ipa":"/raɪts ɪt daʊn/","pos":"phrasal verb","meaning_vi":"ghi lại","example":"My brother always writes it down when he gets a good idea.","example_vi":"Anh trai tôi luôn ghi lại mỗi khi có một ý tưởng hay."},{"word":"looks it up","ipa":"/lʊks ɪt ʌp/","pos":"phrasal verb","meaning_vi":"tra cứu","example":"If she does not know a word, she looks it up in a dictionary.","example_vi":"Nếu không biết một từ, cô ấy sẽ tra trong từ điển."},{"word":"native speakers","ipa":"/ˈneɪtɪv ˈspiːkərz/","pos":"noun phrase","meaning_vi":"người bản ngữ","example":"Native speakers often talk very fast.","example_vi":"Người bản xứ thường nói rất nhanh."},{"word":"confidence","ipa":"/ˈkɑːnfɪdəns/","pos":"noun","meaning_vi":"sự tự tin","example":"Practice gives you confidence before a big presentation.","example_vi":"Luyện tập mang lại cho bạn sự tự tin trước một buổi thuyết trình lớn."},{"word":"fluently","ipa":"/ˈfluːəntli/","pos":"adverb","meaning_vi":"trôi chảy","example":"After living abroad, he spoke Japanese fluently.","example_vi":"Sau khi sống ở nước ngoài, anh ấy nói tiếng Nhật rất trôi chảy."},{"word":"keep going","ipa":"/kiːp ˈɡoʊɪŋ/","pos":"phrase","meaning_vi":"tiếp tục, không bỏ cuộc","example":"The hill is steep, but we have to keep going.","example_vi":"Ngọn đồi rất dốc, nhưng chúng ta phải tiếp tục đi."}],"questions":[{"question":"What is Linh''s secret to improving?","options":["Studying only at weekends","Practising a little every day","Taking expensive classes","Moving abroad"],"answer_index":1,"explanation_vi":"Linh luyện một chút mỗi ngày thay vì nhiều lần một tuần."},{"question":"What does she do when she hears a new word?","options":["She ignores it","She asks her teacher","She writes it down and looks it up later","She translates the whole text"],"answer_index":2,"explanation_vi":"Cô ghi từ mới lại rồi tra sau."},{"question":"How did she feel when she joined the online group?","options":["Angry","Shy at first","Very confident","Bored"],"answer_index":1,"explanation_vi":"Ban đầu cô cảm thấy ngại ngùng."},{"question":"What is the main idea of the passage?","options":["Films are better than books","Mistakes should be avoided","Only native speakers can teach","Patience and daily practice lead to progress"],"answer_index":3,"explanation_vi":"Sự kiên nhẫn và luyện tập hằng ngày giúp tiến bộ."}]}', 'course', 1, 'b1-learning-languages', 'study', 21)
