INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'wancha'), 'Small Changes, Big Impact', 'Cutting down on plastic', 'B1', '{"title":"Small Changes, Big Impact","summary_vi":"Luyện nghe và đọc về cách một người giảm dùng đồ nhựa trong cuộc sống hằng ngày.","sentences":["Sara lives in Melbourne, and last January she decided to cut down on plastic.","She started by counting how many plastic bags she threw away each week.","The number shocked her, so she bought a cloth bag and a reusable water bottle.","Now she refuses plastic straws and brings her own container when she buys takeaway.","At the market, she picks fruit and vegetables that are not wrapped in packaging.","It was not always easy, because many products come in plastic by default.","However, she has found shops that let customers refill bottles with soap and shampoo.","Her friends laughed at first, but several of them have now copied her habits.","Sara knows that one person cannot solve the problem alone.","Still, she believes small changes add up if enough people join in."],"sentences_vi":["Sara sống ở Melbourne, và tháng Một năm ngoái cô quyết định giảm dùng nhựa.","Cô bắt đầu bằng cách đếm xem mỗi tuần mình vứt bao nhiêu túi nhựa.","Con số đó làm cô sốc, nên cô mua một chiếc túi vải và một bình nước dùng nhiều lần.","Giờ cô từ chối ống hút nhựa và tự mang hộp đựng khi mua đồ mang đi.","Ở chợ, cô chọn trái cây và rau củ không bọc trong bao bì.","Không phải lúc nào cũng dễ, vì nhiều sản phẩm mặc định được đựng trong nhựa.","Tuy nhiên, cô đã tìm được những cửa hàng cho khách đổ đầy lại chai xà phòng và dầu gội.","Lúc đầu bạn bè cô cười, nhưng giờ một vài người đã bắt chước thói quen của cô.","Sara biết rằng một người không thể tự mình giải quyết vấn đề này.","Dù vậy, cô tin rằng những thay đổi nhỏ sẽ cộng dồn lại nếu có đủ nhiều người cùng tham gia."],"vocabulary":[{"word":"cut down on","ipa":"/kʌt daʊn ɑːn/","pos":"phrasal verb","meaning_vi":"giảm bớt","example":"We are trying to cut down on energy use at home.","example_vi":"Chúng tôi đang cố giảm mức dùng năng lượng ở nhà."},{"word":"threw away","ipa":"/θruː əˈweɪ/","pos":"phrasal verb","meaning_vi":"vứt đi","example":"He threw away his old shoes after the trip.","example_vi":"Anh ấy đã vứt đôi giày cũ sau chuyến đi."},{"word":"reusable","ipa":"/riˈjuːzəbəl/","pos":"adjective","meaning_vi":"có thể dùng lại","example":"A reusable cup is better for the environment.","example_vi":"Một chiếc cốc dùng nhiều lần thì tốt hơn cho môi trường."},{"word":"packaging","ipa":"/ˈpækɪdʒɪŋ/","pos":"noun","meaning_vi":"bao bì","example":"The packaging was bigger than the gift itself.","example_vi":"Bao bì còn to hơn cả món quà."},{"word":"by default","ipa":"/baɪ dɪˈfɔːlt/","pos":"phrase","meaning_vi":"mặc định","example":"The phone sets the language to English by default.","example_vi":"Điện thoại mặc định đặt ngôn ngữ là tiếng Anh."},{"word":"refill","ipa":"/riːˈfɪl/","pos":"verb","meaning_vi":"đổ đầy lại","example":"You can refill your bottle at the water station.","example_vi":"Bạn có thể đổ đầy lại bình nước ở trạm nước."},{"word":"add up","ipa":"/æd ʌp/","pos":"phrasal verb","meaning_vi":"cộng dồn lại","example":"Small savings add up over a year.","example_vi":"Những khoản tiết kiệm nhỏ cộng dồn lại sau một năm."},{"word":"join in","ipa":"/dʒɔɪn ɪn/","pos":"phrasal verb","meaning_vi":"tham gia cùng","example":"Everyone is welcome to join in the game.","example_vi":"Ai cũng được chào đón tham gia trò chơi."}],"questions":[{"question":"How did Sara begin her plastic-free journey?","options":["She joined a protest","She counted the plastic bags she threw away","She closed her kitchen","She moved to a village"],"answer_index":1,"explanation_vi":"Cô bắt đầu bằng việc đếm số túi nhựa vứt đi mỗi tuần."},{"question":"Why was it difficult for Sara?","options":["Shops are always closed","She could not afford a bag","Plastic is the default packaging for many products","Her friends stopped talking to her"],"answer_index":2,"explanation_vi":"Nhiều sản phẩm mặc định được đựng trong nhựa."},{"question":"What happened to Sara''s friends?","options":["Several of them copied her habits","They moved to another city","They criticised her online","They ignored the topic"],"answer_index":0,"explanation_vi":"Một số bạn đã bắt chước thói quen của cô."},{"question":"What does Sara believe?","options":["One person can fix everything","Plastic is not a problem","Only governments can help","Small changes matter when many people join in"],"answer_index":3,"explanation_vi":"Cô tin những thay đổi nhỏ cộng dồn khi nhiều người cùng làm."}]}', 'course', 1, 'b1-plastic-free', 'nature', 22)
