INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'wancha'), 'Streetside Flavours', 'Street food culture in Vietnam', 'B1', '{"title":"Streetside Flavours","summary_vi":"Luyện nghe và nói về văn hóa ăn vặt vỉa hè đặc sắc ở Hà Nội và Huế.","sentences":["If you visit Vietnam, you should not miss the street food.","In Hanoi, many people start the day with a hot bowl of pho from a small stall.","In Hue, my grandmother''s favourite snack is banh beo, which is served in tiny dishes.","What makes street food special is that every vendor has a recipe passed down in the family.","Prices are low, so students and office workers eat there almost every day.","You usually sit on a plastic stool at the side of the road.","At first, some tourists worry about hygiene, but a busy stall is normally a good sign.","Locals say that if there is a long queue, the food must be fresh and tasty.","Many foreigners who have tried it say that they miss the flavours after going home.","Street food is more than a cheap meal, because it brings neighbours together."],"sentences_vi":["Nếu đến Việt Nam, bạn đừng bỏ lỡ món ăn đường phố.","Ở Hanoi, nhiều người bắt đầu ngày mới với một tô phở nóng hổi từ một quán nhỏ.","Ở Hue, món ăn vặt yêu thích của bà tôi là banh beo, được dọn trong những chiếc đĩa nhỏ xíu.","Điều làm món ăn đường phố trở nên đặc biệt là người bán nào cũng có một công thức truyền lại trong gia đình.","Giá rẻ, nên sinh viên và nhân viên văn phòng ăn ở đó hầu như mỗi ngày.","Thường thì bạn ngồi trên một chiếc ghế nhựa thấp bên lề đường.","Lúc đầu, một số du khách lo lắng về vệ sinh, nhưng một quán đông khách thường là dấu hiệu tốt.","Người địa phương nói rằng nếu có hàng dài người xếp hàng thì đồ ăn chắc chắn tươi và ngon.","Nhiều người nước ngoài đã thử đều nói rằng họ nhớ hương vị ấy sau khi về nước.","Món ăn đường phố không chỉ là một bữa ăn rẻ, mà còn gắn kết những người hàng xóm với nhau."],"vocabulary":[{"word":"street food","ipa":"/striːt fuːd/","pos":"noun","meaning_vi":"đồ ăn đường phố","example":"Street food is cheap and delicious in many Asian cities.","example_vi":"Đồ ăn đường phố vừa rẻ vừa ngon ở nhiều thành phố châu Á."},{"word":"stall","ipa":"/stɔːl/","pos":"noun","meaning_vi":"quầy hàng, sạp","example":"She runs a fruit stall near the station.","example_vi":"Cô ấy bán trái cây ở một sạp gần nhà ga."},{"word":"vendor","ipa":"/ˈvendər/","pos":"noun","meaning_vi":"người bán hàng rong","example":"The vendor sells hot corn every evening.","example_vi":"Người bán hàng bán bắp nướng nóng mỗi buổi tối."},{"word":"passed down","ipa":"/pæst daʊn/","pos":"phrasal verb","meaning_vi":"truyền lại","example":"This song was passed down from my great-grandmother.","example_vi":"Bài hát này được truyền lại từ bà cố của tôi."},{"word":"hygiene","ipa":"/ˈhaɪdʒiːn/","pos":"noun","meaning_vi":"vệ sinh","example":"Good hygiene starts with washing your hands.","example_vi":"Vệ sinh tốt bắt đầu từ việc rửa tay."},{"word":"queue","ipa":"/kjuː/","pos":"noun","meaning_vi":"hàng người xếp hàng","example":"There was a long queue outside the cinema.","example_vi":"Có một hàng dài người xếp hàng bên ngoài rạp chiếu phim."},{"word":"a good sign","ipa":"/ə ɡʊd saɪn/","pos":"phrase","meaning_vi":"dấu hiệu tốt","example":"Her smile was a good sign after the meeting.","example_vi":"Nụ cười của cô ấy là một dấu hiệu tốt sau cuộc họp."}],"questions":[{"question":"How is banh beo served in Hue?","options":["In big bowls","In tiny dishes","On banana leaves only","In plastic bags"],"answer_index":1,"explanation_vi":"Bánh bèo được dọn trong những đĩa nhỏ xíu."},{"question":"Why is street food special according to the passage?","options":["It is always the cheapest","It is only for tourists","Every vendor has a family recipe passed down","It is served in restaurants"],"answer_index":2,"explanation_vi":"Mỗi người bán có công thức gia truyền."},{"question":"What does a long queue usually mean?","options":["The food is fresh and tasty","The stall is closing","The prices are high","The service is slow"],"answer_index":0,"explanation_vi":"Hàng dài thường báo hiệu đồ ăn tươi ngon."},{"question":"What is the final message of the passage?","options":["Tourists should avoid stalls","Hygiene does not matter","Street food only suits students","Street food also brings people together"],"answer_index":3,"explanation_vi":"Đồ ăn vỉa hè không chỉ rẻ mà còn gắn kết hàng xóm."}]}', 'course', 1, 'b1-street-food', 'food', 23)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'wancha'), 'The Home Office Balance', 'Working from home', 'B1', '{"title":"The Home Office Balance","summary_vi":"Luyện nghe và đọc về ưu nhược điểm của việc làm việc tại nhà và cách giữ cân bằng.","sentences":["Since the pandemic, millions of people have started working from home.","My colleague Emma in London has done it for three years now.","She loves skipping the long commute, which gives her an extra hour every morning.","However, she admits that it is hard to separate work from private life.","When her laptop is always on the kitchen table, she tends to answer emails late at night.","To fix this, she created a small workspace in the spare room and set fixed hours.","She also makes a point of going for a walk at lunchtime.","Emma sometimes feels lonely, so she meets her team at a café once a week.","If you work from home, communication becomes even more important.","Short video calls can prevent misunderstandings and help everyone feel connected.","In her opinion, the best solution is a mix of home and office days."],"sentences_vi":["Kể từ đại dịch, hàng triệu người đã bắt đầu làm việc tại nhà.","Đồng nghiệp Emma của tôi ở London đã làm như vậy được ba năm rồi.","Cô ấy thích việc không phải đi lại quãng đường dài, nhờ đó mỗi sáng có thêm một tiếng.","Tuy nhiên, cô thừa nhận rằng rất khó tách biệt công việc với cuộc sống riêng.","Khi laptop lúc nào cũng nằm trên bàn bếp, cô có xu hướng trả lời email vào tận đêm khuya.","Để khắc phục, cô lập một góc làm việc nhỏ trong phòng trống và đặt ra giờ giấc cố định.","Cô cũng chủ động đi dạo vào giờ nghỉ trưa.","Đôi khi Emma thấy cô đơn, nên mỗi tuần cô gặp nhóm của mình ở quán cà phê một lần.","Nếu bạn làm việc tại nhà, giao tiếp càng trở nên quan trọng hơn.","Những cuộc gọi video ngắn có thể tránh hiểu lầm và giúp mọi người cảm thấy gắn kết.","Theo cô, giải pháp tốt nhất là kết hợp những ngày làm ở nhà và ở văn phòng."],"vocabulary":[{"word":"working from home","ipa":"/ˈwɜːrkɪŋ frəm hoʊm/","pos":"phrase","meaning_vi":"làm việc tại nhà","example":"Working from home saves me time and money.","example_vi":"Làm việc tại nhà giúp tôi tiết kiệm thời gian và tiền bạc."},{"word":"commute","ipa":"/kəˈmjuːt/","pos":"noun","meaning_vi":"quãng đường đi làm","example":"My daily commute takes about forty minutes by train.","example_vi":"Quãng đường đi làm hằng ngày của tôi mất khoảng bốn mươi phút đi tàu."},{"word":"separate","ipa":"/ˈsepəreɪt/","pos":"verb","meaning_vi":"tách biệt","example":"It is wise to separate your savings from your daily money.","example_vi":"Tách riêng tiền tiết kiệm khỏi tiền chi tiêu hằng ngày là điều khôn ngoan."},{"word":"tends to","ipa":"/tendz tuː/","pos":"phrase","meaning_vi":"có xu hướng","example":"My brother tends to forget his keys.","example_vi":"Em trai tôi hay quên chìa khóa."},{"word":"fixed hours","ipa":"/fɪkst ˈaʊərz/","pos":"noun phrase","meaning_vi":"giờ làm cố định","example":"The shop keeps fixed hours from nine to six.","example_vi":"Cửa hàng mở cửa theo giờ cố định từ chín giờ đến sáu giờ."},{"word":"makes a point of","ipa":"/meɪks ə pɔɪnt əv/","pos":"phrase","meaning_vi":"luôn cố gắng làm gì","example":"She makes a point of calling her parents every Sunday.","example_vi":"Cô ấy luôn nhớ gọi điện cho bố mẹ vào mỗi Chủ nhật."},{"word":"feel connected","ipa":"/fiːl kəˈnektɪd/","pos":"phrase","meaning_vi":"cảm thấy gắn kết","example":"Group chats help us feel connected when we live far apart.","example_vi":"Các nhóm chat giúp chúng tôi cảm thấy gắn kết khi sống xa nhau."}],"questions":[{"question":"What does Emma like most about working from home?","options":["Cheaper rent","Skipping the long commute","Bigger salary","More meetings"],"answer_index":1,"explanation_vi":"Cô thích không phải đi làm xa và có thêm một giờ mỗi sáng."},{"question":"What problem does she admit having?","options":["Her internet is slow","Her boss is strict","It is hard to separate work from private life","She has no laptop"],"answer_index":2,"explanation_vi":"Cô khó tách biệt công việc và đời sống riêng."},{"question":"How does Emma deal with feeling lonely?","options":["She meets her team at a café weekly","She quits her job","She works at night","She avoids video calls"],"answer_index":0,"explanation_vi":"Cô gặp đồng nghiệp ở quán cà phê mỗi tuần một lần."},{"question":"What does Emma think is the best solution?","options":["Always staying at home","Always working in an office","Working only at night","A mix of home and office days"],"answer_index":3,"explanation_vi":"Theo cô, kết hợp ngày ở nhà và ngày ở văn phòng là tốt nhất."}]}', 'course', 1, 'b1-work-from-home', 'work', 24)
