  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'wancha'), 'My New Coworker Is a Bot', 'AI at work', 'B2', '{"title":"My New Coworker Is a Bot","summary_vi":"Luyện nghe và đọc một bài bình luận về việc trí tuệ nhân tạo thay đổi công việc văn phòng, cùng các cụm từ hay dùng khi nói về công nghệ.","sentences":["When my company introduced an AI assistant last spring, I was convinced it would take my job.","Instead, it took the most tedious parts of it, and I have been wrestling with mixed feelings ever since.","My name is Linh, and I manage a small marketing team in Da Nang.","Reports that once took a whole afternoon are now drafted in minutes, which has freed us up for more creative work.","Had I known how useful it would be, I would have asked for it years ago.","However, the tool is far from flawless, and its confident mistakes can slip under the radar.","Last month a client was almost sent a proposal containing statistics that the software had simply made up.","That is why every output must be double-checked by a human before it goes out.","Some colleagues worry that juniors will never learn the craft if machines do all the groundwork.","I see their point, but I think the real danger is complacency rather than the technology itself.","If we treat AI as a shortcut, we will lose our edge; as a sparring partner, we will sharpen it.","In the long run, the people who thrive will know when to trust the machine and when to overrule it."],"sentences_vi":["Khi công ty đưa trợ lý AI vào sử dụng hồi mùa xuân năm ngoái, tôi đã tin chắc rằng nó sẽ cướp mất việc của mình.","Thay vào đó, nó gánh đi những phần nhàm chán nhất của công việc, và từ đó đến nay tôi luôn có cảm xúc lẫn lộn.","Tôi tên là Linh, quản lý một nhóm marketing nhỏ ở Da Nang.","Những bản báo cáo từng tốn cả buổi chiều giờ được soạn xong trong vài phút, nhờ vậy cả nhóm có thêm thời gian cho những việc sáng tạo hơn.","Giá mà biết trước nó hữu ích đến thế, tôi đã xin trang bị từ nhiều năm trước rồi.","Tuy nhiên, công cụ này còn lâu mới hoàn hảo, và những lỗi sai được nó đưa ra một cách đầy tự tin rất dễ bị bỏ sót.","Tháng trước, một khách hàng suýt nữa đã nhận được bản đề xuất chứa những số liệu mà phần mềm tự bịa ra.","Đó là lý do mọi kết quả đầu ra đều phải được một người kiểm tra lại cẩn thận trước khi gửi đi.","Một số đồng nghiệp lo rằng người mới vào nghề sẽ chẳng bao giờ học được nghề nếu máy móc làm hết phần nền tảng.","Tôi hiểu quan điểm của họ, nhưng tôi nghĩ mối nguy thật sự là sự tự mãn chứ không phải bản thân công nghệ.","Nếu coi AI là con đường tắt, chúng ta sẽ đánh mất lợi thế của mình; còn nếu coi nó là người đối luyện, chúng ta sẽ mài sắc lợi thế ấy.","Về lâu dài, những người thành công sẽ là những người biết khi nào nên tin máy và khi nào nên bác bỏ nó."],"vocabulary":[{"word":"tedious","ipa":"/ˈtiːdiəs/","pos":"adjective","meaning_vi":"tẻ nhạt, nhàm chán","example":"Copying numbers from one spreadsheet to another is a tedious task.","example_vi":"Việc chép số liệu từ bảng tính này sang bảng tính khác là một công việc nhàm chán."},{"word":"wrestling with","ipa":"/ˈrɛslɪŋ wɪð/","pos":"phrase","meaning_vi":"vật lộn với (vấn đề, cảm xúc)","example":"She has been wrestling with the decision to change careers.","example_vi":"Cô ấy đã vật lộn với quyết định đổi nghề từ lâu nay."},{"word":"slip under the radar","ipa":"/slɪp ˈʌndər ðə ˈreɪdɑːr/","pos":"idiom","meaning_vi":"lọt qua mà không bị chú ý","example":"Small errors in the budget can easily slip under the radar.","example_vi":"Những sai sót nhỏ trong ngân sách rất dễ bị bỏ sót."},{"word":"made up","ipa":"/meɪd ʌp/","pos":"phrasal verb","meaning_vi":"bịa ra","example":"He made up an excuse because he had forgotten the meeting.","example_vi":"Anh ấy bịa ra một cái cớ vì đã quên mất buổi họp."},{"word":"complacency","ipa":"/kəmˈpleɪsənsi/","pos":"noun","meaning_vi":"sự tự mãn, chủ quan","example":"Success often breeds complacency in large companies.","example_vi":"Thành công thường nuôi dưỡng sự tự mãn trong các công ty lớn."},{"word":"lose our edge","ipa":"/luːz ˈaʊər ɛdʒ/","pos":"idiom","meaning_vi":"mất lợi thế cạnh tranh","example":"If we stop learning new skills, we will lose our edge in the market.","example_vi":"Nếu ngừng học kỹ năng mới, chúng ta sẽ mất đi lợi thế cạnh tranh trên thị trường."},{"word":"sparring partner","ipa":"/ˈspɑːrɪŋ ˈpɑːrtnər/","pos":"noun","meaning_vi":"người cùng tranh luận, đối trọng giúp mình giỏi lên","example":"My brother is my favourite sparring partner when I rehearse debates.","example_vi":"Anh trai tôi là người đối luyện tuyệt vời nhất mỗi khi tôi tập tranh biện."},{"word":"in the long run","ipa":"/ɪn ðə lɔːŋ rʌn/","pos":"idiom","meaning_vi":"về lâu dài","example":"Cheap tools can cost you more in the long run.","example_vi":"Những công cụ rẻ tiền về lâu dài có thể khiến bạn tốn kém hơn."}],"questions":[{"question":"How did the AI assistant change Linh''s work?","options":["It replaced her whole team","It took over the boring tasks and left time for creative work","It made reports take longer","It forced her to move to another city"],"answer_index":1,"explanation_vi":"Công cụ AI đảm nhận phần việc tẻ nhạt nên cả nhóm có thêm thời gian cho việc sáng tạo."},{"question":"Why must every output be double-checked by a human?","options":["The software is too slow","Clients dislike automated reports","The tool can state false information with confidence","Managers do not trust any technology"],"answer_index":2,"explanation_vi":"Phần mềm từng tự bịa ra số liệu mà vẫn tỏ ra rất chắc chắn."},{"question":"What does the writer see as the biggest danger?","options":["Becoming complacent about relying on AI","Machines becoming too intelligent","Juniors earning too much","Companies refusing to adopt new tools"],"answer_index":0,"explanation_vi":"Tác giả cho rằng mối nguy thật sự là sự chủ quan chứ không phải bản thân công nghệ."},{"question":"What can be inferred about the writer''s attitude to AI?","options":["Strongly opposed to it","Blindly enthusiastic","Cautiously positive","Completely indifferent"],"answer_index":2,"explanation_vi":"Bà ghi nhận lợi ích nhưng vẫn nhấn mạnh việc kiểm tra và dùng có chừng mực."}]}', 'course', 1, 'b2-ai-at-work', 'tech', 25)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'wancha'), 'The Day My Brain Pulled the Plug', 'Burnout and mental health', 'B2', '{"title":"The Day My Brain Pulled the Plug","summary_vi":"Luyện đọc và nghe một bài tiểu luận cá nhân về kiệt sức do công việc, cùng các từ vựng nói về sức khỏe tinh thần.","sentences":["Two winters ago, I stopped being able to read my own emails.","The words were there, but my brain refused to hold them, as if someone had pulled the plug.","I was a software engineer in Ho Chi Minh City, and I had been running on empty for almost a year.","At the time, I called it tiredness and told myself that a long weekend would fix everything.","It was only when my sister noticed that I had stopped laughing that I finally saw a doctor.","Burnout, she explained, is not simply being overworked; it is chronic exhaustion mixed with cynicism and falling performance.","If I had taken the early warning signs seriously, I might not have lost three months to recovery.","Part of the problem was a culture that treats exhaustion as a badge of honour.","Staying late was praised, and taking a day off was quietly seen as a lack of commitment.","Recovery meant setting firm boundaries, such as switching off notifications after seven in the evening.","It also meant asking for help, which turned out to be harder than any coding problem.","Today I still care about my work, but I no longer let it define my worth."],"sentences_vi":["Hai mùa đông trước, tôi bỗng không còn đọc nổi email của chính mình.","Chữ vẫn ở đó, nhưng não tôi không chịu ghi nhớ chúng, như thể có ai đó đã rút phích cắm.","Tôi từng là kỹ sư phần mềm ở Ho Chi Minh City, và đã chạy trong tình trạng cạn kiệt năng lượng suốt gần một năm.","Lúc đó tôi gọi đó là mệt mỏi và tự nhủ rằng một kỳ nghỉ cuối tuần dài sẽ giải quyết được tất cả.","Mãi đến khi chị gái nhận ra tôi không còn cười nữa, tôi mới chịu đi khám bác sĩ.","Bác sĩ giải thích rằng kiệt sức không đơn giản là làm việc quá sức; đó là tình trạng mệt mỏi kéo dài đi kèm sự hoài nghi, chán chường và hiệu suất sa sút.","Nếu tôi nghiêm túc xem xét những dấu hiệu cảnh báo sớm, có lẽ tôi đã không mất ba tháng để hồi phục.","Một phần vấn đề nằm ở thứ văn hóa coi sự kiệt sức như một huy hiệu danh dự.","Ở lại muộn thì được khen, còn nghỉ một ngày thì bị ngầm cho là thiếu tận tâm.","Hồi phục nghĩa là đặt ra những ranh giới rõ ràng, chẳng hạn như tắt thông báo sau bảy giờ tối.","Nó cũng có nghĩa là biết nhờ người giúp, điều mà hóa ra còn khó hơn bất kỳ bài toán lập trình nào.","Ngày nay tôi vẫn quan tâm đến công việc, nhưng tôi không còn để nó quyết định giá trị của bản thân nữa."],"vocabulary":[{"word":"pulled the plug","ipa":"/pʊld ðə plʌɡ/","pos":"idiom","meaning_vi":"ngắt, dừng hẳn (như rút phích cắm)","example":"The investors pulled the plug on the project after two years.","example_vi":"Các nhà đầu tư đã dừng hẳn dự án sau hai năm."},{"word":"running on empty","ipa":"/ˈrʌnɪŋ ɑːn ˈɛmpti/","pos":"idiom","meaning_vi":"cạn kiệt năng lượng mà vẫn cố làm","example":"By the end of exam season, most students are running on empty.","example_vi":"Đến cuối mùa thi, hầu hết học sinh đều đã cạn kiệt sức lực."},{"word":"chronic","ipa":"/ˈkrɑːnɪk/","pos":"adjective","meaning_vi":"mãn tính, kéo dài","example":"Chronic stress can weaken your immune system.","example_vi":"Căng thẳng kéo dài có thể làm suy yếu hệ miễn dịch của bạn."},{"word":"cynicism","ipa":"/ˈsɪnɪsɪzəm/","pos":"noun","meaning_vi":"thói hoài nghi, bi quan","example":"Years of broken promises had left him with a deep cynicism about politics.","example_vi":"Nhiều năm thất hứa đã để lại trong anh ấy một sự hoài nghi sâu sắc về chính trị."},{"word":"warning signs","ipa":"/ˈwɔːrnɪŋ saɪnz/","pos":"noun","meaning_vi":"dấu hiệu cảnh báo","example":"Constant headaches can be one of the warning signs of overwork.","example_vi":"Những cơn đau đầu liên miên có thể là một trong những dấu hiệu cảnh báo của việc làm việc quá sức."},{"word":"a badge of honour","ipa":"/ə bædʒ əv ˈɑːnər/","pos":"idiom","meaning_vi":"niềm tự hào, thứ để khoe","example":"For some people, sleeping only four hours is a badge of honour.","example_vi":"Với một số người, chỉ ngủ bốn tiếng một ngày là điều đáng tự hào."},{"word":"firm boundaries","ipa":"/fɜːrm ˈbaʊndriz/","pos":"noun","meaning_vi":"ranh giới rõ ràng","example":"Parents who set firm boundaries usually raise more confident children.","example_vi":"Những bậc cha mẹ đặt ra ranh giới rõ ràng thường nuôi dạy được những đứa con tự tin hơn."}],"questions":[{"question":"What was the first sign that something was wrong?","options":["He lost his job","He could no longer take in the words of his emails","He moved to another country","He stopped using his phone"],"answer_index":1,"explanation_vi":"Ông không thể đọc nổi email của chính mình vì não không tiếp nhận được chữ."},{"question":"According to the writer''s sister, burnout is","options":["the same as feeling tired","caused only by laziness","a short-term reaction to a bad week","a long-lasting state of exhaustion with other symptoms"],"answer_index":3,"explanation_vi":"Kiệt sức là sự mệt mỏi kéo dài kèm hoài nghi và hiệu suất giảm sút."},{"question":"What does the writer criticise about workplace culture?","options":["It praises people who exhaust themselves","It pays too little","It bans weekends","It offers too many holidays"],"answer_index":0,"explanation_vi":"Văn hóa công sở coi việc kiệt sức như một huy hiệu danh dự."},{"question":"What does the final sentence suggest?","options":["He has left his career for good","He now values himself beyond his job","He regrets asking for help","He works longer hours than before"],"answer_index":1,"explanation_vi":"Anh vẫn quan tâm công việc nhưng không còn lấy nó làm thước đo giá trị bản thân."}]}', 'course', 1, 'b2-burnout', 'health', 26)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'wancha'), 'Freedom on Two Wheels', 'The gig economy', 'B2', '{"title":"Freedom on Two Wheels","summary_vi":"Luyện nghe và đọc một bản tin chuyên đề về lao động tự do qua ứng dụng, với từ vựng về hợp đồng, thu nhập và quyền lợi.","sentences":["Every morning at six, Minh Tuan switches on his phone and waits for the first delivery request to arrive.","He is one of hundreds of thousands of ride-hailing and delivery drivers working in Vietnam''s big cities.","For many of them, gig work offers a flexibility that traditional jobs simply cannot match.","Drivers choose their own hours, and some earn more than they did in factories.","Yet this freedom comes at a price, since gig workers are classed as independent contractors rather than employees.","They receive no paid leave, no sick pay and, in many cases, no insurance unless they arrange it themselves.","Income can also be unpredictable, as the platforms adjust their commission rates with little warning.","\"One week I make a decent living, and the next I barely break even,\" Minh Tuan says.","Lawmakers in several countries are now debating whether these workers deserve a new legal category.","Supporters of the gig model argue that stricter rules would drive companies out and cost jobs.","Critics reply that a business built on workers'' insecurity is not sustainable in the long term.","Whatever the outcome, it is clear that the way we define work is being rewritten."],"sentences_vi":["Mỗi sáng lúc sáu giờ, Minh Tuan bật điện thoại và chờ yêu cầu giao hàng đầu tiên đến.","Anh là một trong hàng trăm nghìn tài xế xe công nghệ và giao hàng đang làm việc tại các thành phố lớn ở Việt Nam.","Với nhiều người trong số họ, công việc tự do mang lại sự linh hoạt mà các công việc truyền thống đơn giản là không thể sánh được.","Tài xế tự chọn giờ làm, và một số người kiếm được nhiều hơn hồi làm trong nhà máy.","Tuy nhiên, sự tự do này phải trả giá, vì người làm việc tự do được xếp vào nhóm nhà thầu độc lập chứ không phải nhân viên.","Họ không có nghỉ phép hưởng lương, không có trợ cấp ốm đau và trong nhiều trường hợp cũng không có bảo hiểm, trừ khi tự lo.","Thu nhập cũng khó đoán, vì các nền tảng điều chỉnh mức hoa hồng mà ít khi báo trước.","\"Có tuần tôi kiếm được khá, tuần sau thì chỉ vừa đủ hòa vốn,\" Minh Tuan nói.","Các nhà làm luật ở nhiều quốc gia hiện đang tranh luận xem những người lao động này có xứng đáng được xếp vào một nhóm pháp lý mới hay không.","Những người ủng hộ mô hình việc làm tự do cho rằng quy định chặt chẽ hơn sẽ khiến các công ty rời đi và làm mất việc làm.","Những người phản đối đáp lại rằng một doanh nghiệp xây dựng trên sự bấp bênh của người lao động thì không thể bền vững về lâu dài.","Dù kết quả ra sao, rõ ràng cách chúng ta định nghĩa công việc đang được viết lại."],"vocabulary":[{"word":"comes at a price","ipa":"/kʌmz æt ə praɪs/","pos":"idiom","meaning_vi":"phải trả giá, có cái giá đi kèm","example":"Fast growth often comes at a price, usually in the form of stress.","example_vi":"Tăng trưởng nhanh thường phải trả giá, thường là dưới dạng căng thẳng."},{"word":"independent contractors","ipa":"/ˌɪndɪˈpɛndənt ˈkɑːntræktərz/","pos":"noun","meaning_vi":"người làm hợp đồng độc lập","example":"Many designers work as independent contractors for several clients.","example_vi":"Nhiều nhà thiết kế làm việc như những nhà thầu độc lập cho nhiều khách hàng."},{"word":"paid leave","ipa":"/peɪd liːv/","pos":"noun","meaning_vi":"nghỉ phép có lương","example":"New parents in some countries receive a year of paid leave.","example_vi":"Ở một số nước, các bậc cha mẹ mới sinh con được nghỉ phép hưởng lương một năm."},{"word":"commission","ipa":"/kəˈmɪʃən/","pos":"noun","meaning_vi":"tiền hoa hồng","example":"The salesman earns a ten percent commission on every phone he sells.","example_vi":"Anh nhân viên bán hàng nhận mười phần trăm hoa hồng cho mỗi chiếc điện thoại bán được."},{"word":"make a decent living","ipa":"/meɪk ə ˈdiːsənt ˈlɪvɪŋ/","pos":"phrase","meaning_vi":"kiếm đủ sống tử tế","example":"It is hard to make a decent living as a freelance musician.","example_vi":"Rất khó để kiếm sống khá giả với nghề nhạc sĩ tự do."},{"word":"break even","ipa":"/breɪk ˈiːvən/","pos":"phrasal verb","meaning_vi":"hòa vốn","example":"The new café hopes to break even by the end of the year.","example_vi":"Quán cà phê mới hy vọng hòa vốn vào cuối năm nay."},{"word":"sustainable","ipa":"/səˈsteɪnəbəl/","pos":"adjective","meaning_vi":"bền vững","example":"A sustainable business model does not depend on exhausting its workers.","example_vi":"Một mô hình kinh doanh bền vững không dựa vào việc vắt kiệt sức người lao động."}],"questions":[{"question":"What attracts many people to gig work?","options":["Guaranteed pensions","The freedom to choose their hours","Free insurance","Fixed monthly salaries"],"answer_index":1,"explanation_vi":"Tài xế được tự chọn giờ làm, điều mà công việc truyền thống khó đáp ứng."},{"question":"Why can gig workers'' income be hard to predict?","options":["They are paid in foreign currency","Customers rarely order anything","Platforms may change their commission rates suddenly","They must pay for fuel in advance"],"answer_index":2,"explanation_vi":"Các nền tảng điều chỉnh mức hoa hồng mà ít khi báo trước."},{"question":"What is the main argument of supporters of the gig model?","options":["Strict rules could harm companies and reduce jobs","Drivers should be paid less","Insurance is unnecessary","Traditional jobs are better"],"answer_index":0,"explanation_vi":"Họ cho rằng luật chặt hơn có thể khiến công ty rút đi và mất việc làm."},{"question":"What is the tone of the final sentence?","options":["Humorous","Thoughtful about a broader change","Angry at the drivers","Certain about the result"],"answer_index":1,"explanation_vi":"Câu cuối nhận định rằng khái niệm về công việc đang được viết lại, không khẳng định kết quả."}]}', 'course', 1, 'b2-gig-economy', 'work', 27)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
