INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'wancha'), 'A Ticket to Walk Down My Own Street', 'Tourism and local communities', 'B2', '{"title":"A Ticket to Walk Down My Own Street","summary_vi":"Luyện nghe và đọc một bản tin về du lịch quá tải và ảnh hưởng đến cộng đồng địa phương, cùng các cụm từ về du lịch có trách nhiệm.","sentences":["In the old quarter of Hoi An, residents now joke that they need a ticket to walk down their own street.","The town welcomed millions of visitors last year, far more than its narrow lanes were ever designed to handle.","Tourism has undoubtedly brought wealth, but it has also pushed up rents and driven out long-standing families.","Shops that once sold hardware and rice are being replaced by souvenir stalls and cafés aimed at foreigners.","The same story is told in Venice, Barcelona and Kyoto, where locals have staged protests against the crowds.","Some cities have responded by capping visitor numbers or charging an entrance fee on busy days.","Others encourage travellers to explore lesser-known districts, so that the pressure is spread more evenly.","Had authorities acted sooner, many communities might have avoided the resentment now spilling over.","Experts stress that tourists are not the enemy; it is unmanaged growth that does the damage.","Travellers can make a difference by staying in locally owned guesthouses and eating where residents eat.","They can also avoid peak season, when the strain on water and waste services is at its worst.","After all, a destination that loses its soul has little left to offer."],"sentences_vi":["Ở khu phố cổ Hoi An, người dân giờ đây đùa rằng họ phải mua vé mới được đi trên chính con phố của mình.","Năm ngoái thị trấn đón hàng triệu du khách, nhiều hơn rất nhiều so với sức chứa mà những con ngõ hẹp của nó từng được thiết kế.","Du lịch chắc chắn đã mang lại sự giàu có, nhưng nó cũng đẩy giá thuê nhà lên cao và khiến những gia đình sống lâu đời phải rời đi.","Những cửa hàng từng bán đồ sắt và gạo đang bị thay thế bằng các quầy quà lưu niệm và quán cà phê nhắm vào khách nước ngoài.","Câu chuyện tương tự cũng diễn ra ở Venice, Barcelona và Kyoto, nơi người dân địa phương đã tổ chức biểu tình phản đối đám đông du khách.","Một số thành phố đã ứng phó bằng cách giới hạn lượng du khách hoặc thu phí vào cửa vào những ngày đông.","Những nơi khác khuyến khích du khách khám phá các khu vực ít người biết hơn, để áp lực được phân bổ đều hơn.","Giá như chính quyền hành động sớm hơn, nhiều cộng đồng có lẽ đã tránh được sự bực bội đang tràn ra hiện nay.","Các chuyên gia nhấn mạnh rằng du khách không phải là kẻ thù; chính sự tăng trưởng không được kiểm soát mới gây ra thiệt hại.","Du khách có thể tạo ra sự khác biệt bằng cách ở nhà nghỉ do người địa phương làm chủ và ăn ở những quán mà người dân vẫn ăn.","Họ cũng có thể tránh mùa cao điểm, khi các dịch vụ cấp nước và xử lý rác phải chịu áp lực nặng nề nhất.","Suy cho cùng, một điểm đến đánh mất linh hồn thì chẳng còn gì nhiều để mang đến cho du khách."],"vocabulary":[{"word":"pushed up","ipa":"/pʊʃt ʌp/","pos":"phrasal verb","meaning_vi":"đẩy (giá) lên","example":"The new airport pushed up property prices across the region.","example_vi":"Sân bay mới đã đẩy giá bất động sản trong khu vực lên cao."},{"word":"driven out","ipa":"/ˈdrɪvən aʊt/","pos":"phrasal verb","meaning_vi":"bị đuổi đi, buộc phải rời","example":"Small bakeries were driven out by the big supermarket chains.","example_vi":"Những tiệm bánh nhỏ bị các chuỗi siêu thị lớn đẩy ra khỏi thị trường."},{"word":"capping","ipa":"/ˈkæpɪŋ/","pos":"verb","meaning_vi":"đặt mức trần, giới hạn","example":"The council is considering capping the number of tour buses downtown.","example_vi":"Hội đồng đang cân nhắc việc giới hạn số lượng xe buýt du lịch trong trung tâm thành phố."},{"word":"spilling over","ipa":"/ˈspɪlɪŋ ˈoʊvər/","pos":"phrasal verb","meaning_vi":"tràn ra, bùng phát","example":"The argument was spilling over into every family dinner.","example_vi":"Cuộc tranh cãi đang lan sang cả những bữa cơm gia đình."},{"word":"unmanaged","ipa":"/ʌnˈmænɪdʒd/","pos":"adjective","meaning_vi":"không được quản lý","example":"Unmanaged waste has turned the beach into a health hazard.","example_vi":"Rác thải không được quản lý đã biến bãi biển thành mối nguy hại cho sức khỏe."},{"word":"make a difference","ipa":"/meɪk ə ˈdɪfrəns/","pos":"idiom","meaning_vi":"tạo ra khác biệt, có tác động","example":"Even small donations can make a difference to a village school.","example_vi":"Ngay cả những khoản quyên góp nhỏ cũng có thể tạo ra khác biệt cho một ngôi trường làng."},{"word":"peak season","ipa":"/piːk ˈsiːzən/","pos":"noun","meaning_vi":"mùa cao điểm","example":"Hotel rooms are twice as expensive during peak season.","example_vi":"Giá phòng khách sạn đắt gấp đôi vào mùa cao điểm."}],"questions":[{"question":"What do Hoi An residents mean by their joke about a ticket?","options":["Streets are now privately owned","Crowds make it hard to move around their own neighbourhood","Local transport is free","Visitors must pay locals"],"answer_index":1,"explanation_vi":"Đó là cách nói đùa về việc phố cổ quá đông đến mức dân địa phương khó đi lại."},{"question":"What is one negative effect of tourism mentioned?","options":["Fewer foreign investors","Lower wages for guides","Cleaner rivers","Rising rents that push out long-term residents"],"answer_index":3,"explanation_vi":"Giá thuê nhà tăng khiến nhiều gia đình sống lâu năm phải rời đi."},{"question":"What do experts say about the cause of the damage?","options":["Tourists themselves are to blame","Growth that is not managed properly","Bad weather","Poor hotel service"],"answer_index":1,"explanation_vi":"Chuyên gia nhấn mạnh thủ phạm là sự tăng trưởng không được quản lý, không phải du khách."},{"question":"What can be inferred from the sentence beginning ''Had authorities acted sooner''?","options":["Authorities acted quickly enough","Tensions could have been reduced with earlier action","Residents want more tourists","The problem is exaggerated"],"answer_index":1,"explanation_vi":"Câu điều kiện đảo ngữ ngụ ý rằng hành động sớm hơn có thể đã tránh được sự phẫn nộ."}]}', 'course', 1, 'b2-overtourism', 'travel', 28)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'wancha'), 'The Five-Dollar T-Shirt', 'The true cost of fast fashion', 'B2', '{"title":"The Five-Dollar T-Shirt","summary_vi":"Luyện nghe và đọc một bài nói kiểu podcast về tác động của thời trang nhanh lên môi trường và người lao động.","sentences":["Welcome back to the show.","Today I want to talk about the T-shirt you bought for the price of a coffee.","Fast fashion thrives on speed, turning catwalk trends into cheap clothes in a matter of weeks.","The industry now produces roughly twice as many garments as it did twenty years ago.","Much of that clothing is worn only a handful of times before it ends up in landfill.","A single pair of jeans can consume thousands of litres of water, while textile dyeing pollutes rivers in many countries.","Synthetic fibres such as polyester shed microplastics every time they are washed.","Meanwhile, the workers who stitch these garments are often paid wages that barely cover rent.","It would be easy to blame shoppers, but the system is designed to make buying feel effortless.","If brands were held accountable for the waste they create, prices would probably reflect the real cost.","Until then, the most sustainable garment is the one already hanging in your wardrobe.","So before you hit the buy button, ask yourself whether you will still love it in thirty wears."],"sentences_vi":["Chào mừng các bạn quay trở lại với chương trình.","Hôm nay tôi muốn nói về chiếc áo phông mà bạn đã mua với giá một ly cà phê.","Thời trang nhanh phát triển mạnh nhờ tốc độ, biến các xu hướng trên sàn diễn thành quần áo giá rẻ chỉ trong vài tuần.","Ngành này hiện sản xuất lượng quần áo nhiều gấp khoảng hai lần so với hai mươi năm trước.","Phần lớn số quần áo đó chỉ được mặc vài lần rồi bị vứt ra bãi rác.","Chỉ một chiếc quần jeans có thể tiêu tốn hàng nghìn lít nước, trong khi việc nhuộm vải gây ô nhiễm sông ngòi ở nhiều quốc gia.","Các loại sợi tổng hợp như polyester thải ra vi nhựa mỗi lần giặt.","Trong khi đó, những người công nhân may các món đồ này thường nhận mức lương chỉ vừa đủ trả tiền thuê nhà.","Thật dễ để đổ lỗi cho người mua sắm, nhưng cả hệ thống được thiết kế để khiến việc mua hàng trở nên dễ dàng như không.","Nếu các thương hiệu phải chịu trách nhiệm về lượng rác thải mình tạo ra, giá cả có lẽ sẽ phản ánh đúng chi phí thực.","Cho đến lúc đó, món đồ bền vững nhất chính là món đã nằm sẵn trong tủ quần áo của bạn.","Vì vậy, trước khi bấm nút mua, hãy tự hỏi liệu bạn có còn yêu thích nó sau ba mươi lần mặc hay không."],"vocabulary":[{"word":"thrives on","ipa":"/θraɪvz ɑːn/","pos":"phrasal verb","meaning_vi":"phát triển mạnh nhờ vào","example":"Social media thrives on attention and quick reactions.","example_vi":"Mạng xã hội phát triển mạnh nhờ sự chú ý và những phản ứng nhanh chóng."},{"word":"in a matter of weeks","ipa":"/ɪn ə ˈmætər əv wiːks/","pos":"phrase","meaning_vi":"chỉ trong vài tuần","example":"The little shop became famous in a matter of weeks.","example_vi":"Cửa hàng nhỏ ấy trở nên nổi tiếng chỉ trong vài tuần."},{"word":"ends up in landfill","ipa":"/ɛndz ʌp ɪn ˈlændfɪl/","pos":"phrase","meaning_vi":"cuối cùng bị đổ ra bãi rác","example":"Most plastic packaging ends up in landfill within a year.","example_vi":"Hầu hết bao bì nhựa kết thúc ở bãi rác trong vòng một năm."},{"word":"shed","ipa":"/ʃɛd/","pos":"verb","meaning_vi":"rụng ra, thải ra","example":"My cat sheds hair all over the sofa in summer.","example_vi":"Con mèo của tôi rụng lông khắp ghế sofa vào mùa hè."},{"word":"barely cover","ipa":"/ˈbɛrli ˈkʌvər/","pos":"phrase","meaning_vi":"chỉ vừa đủ trang trải","example":"Her scholarship will barely cover her tuition, let alone living costs.","example_vi":"Học bổng của cô ấy chỉ vừa đủ trả học phí, chứ đừng nói đến chi phí sinh hoạt."},{"word":"held accountable","ipa":"/hɛld əˈkaʊntəbəl/","pos":"phrase","meaning_vi":"bị buộc phải chịu trách nhiệm","example":"Company directors should be held accountable for serious safety failures.","example_vi":"Các giám đốc công ty phải chịu trách nhiệm về những sai phạm nghiêm trọng về an toàn."},{"word":"sustainable","ipa":"/səˈsteɪnəbəl/","pos":"adjective","meaning_vi":"bền vững, thân thiện với môi trường","example":"Bamboo is a sustainable alternative to plastic straws.","example_vi":"Tre là một giải pháp bền vững thay cho ống hút nhựa."}],"questions":[{"question":"How does fast fashion work, according to the speaker?","options":["It makes clothes designed to last decades","It copies trends and sells them cheaply within weeks","It sells only in luxury stores","It produces fewer clothes every year"],"answer_index":1,"explanation_vi":"Thời trang nhanh biến xu hướng sàn diễn thành quần áo giá rẻ chỉ trong vài tuần."},{"question":"Which environmental problem is linked to washing synthetic clothes?","options":["Air pollution","Microplastics entering waterways","Soil erosion","Noise pollution"],"answer_index":1,"explanation_vi":"Sợi tổng hợp như polyester thải ra vi nhựa mỗi lần giặt."},{"question":"What does the speaker say about blaming shoppers?","options":["Shoppers are the only cause","It is easy, but the system is built to encourage buying","Shoppers have no choice at all","Brands never advertise"],"answer_index":1,"explanation_vi":"Người nói cho rằng hệ thống được thiết kế để việc mua sắm trở nên dễ dàng nên không chỉ đổ lỗi cho người mua."},{"question":"What is the speaker''s final advice?","options":["Never buy clothes again","Buy only the cheapest items","Think about long-term use before buying","Give old clothes to the factory"],"answer_index":2,"explanation_vi":"Người nói khuyên tự hỏi liệu mình còn thích món đồ sau ba mươi lần mặc hay không."}]}', 'course', 1, 'b2-fast-fashion', 'nature', 29)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
