INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'wancha'), 'Pause, Rewind, Repeat', 'Online learning versus the classroom', 'B2', '{"title":"Pause, Rewind, Repeat","summary_vi":"Luyện nghe và đọc một bài bình luận so sánh học trực tuyến với học trên lớp, cùng các liên từ nối ý quan trọng.","sentences":["When classes moved online in 2020, I assumed it would be a temporary inconvenience.","Five years on, I am a university lecturer in Hanoi who teaches half of her courses through a screen.","Online learning has undeniably widened access, allowing a farmer''s daughter in Gia Lai to attend lectures from top universities.","It also lets students learn at their own pace, pausing and replaying a difficult explanation as often as they need.","Yet I have noticed that motivation tends to evaporate without the structure of a physical timetable.","Completion rates for free courses are strikingly low, often falling below ten percent.","In a classroom, a confused face is noticed immediately, whereas on a video call it is easily hidden behind a muted camera.","Casual conversations in corridors, which shape friendships and ideas, are almost impossible to replicate online.","That said, I would not want to go back to a purely traditional model.","The best results come from blended learning, where lectures are watched at home and class time goes on discussion.","Whichever format is chosen, success depends less on the technology than on the quality of the teaching.","A mediocre lecture does not become inspiring simply because it is streamed."],"sentences_vi":["Khi các lớp học chuyển sang trực tuyến năm 2020, tôi tưởng đó chỉ là một sự bất tiện tạm thời.","Năm năm sau, tôi là giảng viên đại học ở Hanoi, dạy một nửa số môn của mình qua màn hình.","Học trực tuyến rõ ràng đã mở rộng cơ hội tiếp cận, cho phép con gái của một người nông dân ở Gia Lai theo học các bài giảng của những trường đại học hàng đầu.","Nó cũng cho phép sinh viên học theo tốc độ riêng, tạm dừng và xem lại một phần giải thích khó bao nhiêu lần tùy ý.","Tuy vậy, tôi nhận thấy động lực thường tan biến khi không có nề nếp của một thời khóa biểu thực tế.","Tỷ lệ hoàn thành các khóa học miễn phí thấp đến đáng ngạc nhiên, thường dưới mười phần trăm.","Trong lớp học, một gương mặt bối rối được nhận ra ngay lập tức, còn trong cuộc gọi video thì nó dễ dàng bị giấu sau chiếc camera đã tắt.","Những cuộc trò chuyện tình cờ ngoài hành lang, vốn góp phần hình thành tình bạn và ý tưởng, hầu như không thể tái tạo trên mạng.","Dù vậy, tôi cũng không muốn quay lại hoàn toàn với mô hình truyền thống.","Kết quả tốt nhất đến từ hình thức học kết hợp, trong đó bài giảng được xem ở nhà còn thời gian trên lớp dành cho thảo luận.","Dù chọn hình thức nào, thành công phụ thuộc vào chất lượng giảng dạy nhiều hơn là công nghệ.","Một bài giảng tầm thường không trở nên truyền cảm hứng chỉ vì được phát trực tuyến."],"vocabulary":[{"word":"widened access","ipa":"/ˈwaɪdənd ˈæksɛs/","pos":"phrase","meaning_vi":"mở rộng khả năng tiếp cận","example":"Public libraries have widened access to books for poor families.","example_vi":"Các thư viện công cộng đã mở rộng cơ hội tiếp cận sách cho các gia đình nghèo."},{"word":"at their own pace","ipa":"/æt ðɛr oʊn peɪs/","pos":"phrase","meaning_vi":"theo tốc độ của riêng mình","example":"Children should be allowed to read at their own pace.","example_vi":"Trẻ em nên được phép đọc theo tốc độ của riêng mình."},{"word":"evaporate","ipa":"/ɪˈvæpəreɪt/","pos":"verb","meaning_vi":"tan biến, bay mất","example":"My enthusiasm began to evaporate after the third rainy day.","example_vi":"Sự nhiệt tình của tôi bắt đầu tan biến sau ngày mưa thứ ba."},{"word":"completion rates","ipa":"/kəmˈpliːʃən reɪts/","pos":"noun","meaning_vi":"tỷ lệ hoàn thành","example":"Completion rates rise when courses include short quizzes.","example_vi":"Tỷ lệ hoàn thành tăng lên khi các khóa học có những bài kiểm tra ngắn."},{"word":"replicate","ipa":"/ˈrɛplɪkeɪt/","pos":"verb","meaning_vi":"tái tạo, sao chép lại","example":"No app can replicate the atmosphere of a live concert.","example_vi":"Không ứng dụng nào có thể tái tạo được bầu không khí của một buổi hòa nhạc trực tiếp."},{"word":"blended learning","ipa":"/ˈblɛndɪd ˈlɜːrnɪŋ/","pos":"noun","meaning_vi":"học kết hợp (trực tuyến và trực tiếp)","example":"Our school adopted blended learning to make better use of class time.","example_vi":"Trường chúng tôi áp dụng học kết hợp để tận dụng thời gian trên lớp tốt hơn."},{"word":"that said","ipa":"/ðæt sɛd/","pos":"phrase","meaning_vi":"tuy nhiên, dẫu vậy","example":"The film was too long; that said, the ending was brilliant.","example_vi":"Bộ phim quá dài; dù vậy, đoạn kết thật tuyệt vời."}],"questions":[{"question":"What is one advantage of online learning mentioned?","options":["It is always cheaper than school","It lets students from remote areas attend top lectures","It removes the need for teachers","It guarantees better grades"],"answer_index":1,"explanation_vi":"Học trực tuyến giúp cả những học sinh ở vùng xa tham dự bài giảng của trường hàng đầu."},{"question":"Why does the writer say a confused student is harder to spot online?","options":["Students never ask questions","Cameras and microphones can be switched off","Lectures are too short","Teachers avoid eye contact"],"answer_index":1,"explanation_vi":"Sinh viên có thể tắt camera hoặc micro nên khó nhận ra vẻ bối rối."},{"question":"What does the writer prefer?","options":["Purely online courses","Purely traditional classrooms","A mix of home lectures and in-class discussion","Free courses only"],"answer_index":2,"explanation_vi":"Tác giả thấy kết quả tốt nhất đến từ mô hình học kết hợp."},{"question":"What is the point of the last sentence?","options":["Streaming makes lessons more fun","Technology cannot fix poor teaching","Lectures should be shorter","Video lessons are always mediocre"],"answer_index":1,"explanation_vi":"Bài giảng tệ không thể trở nên hay chỉ vì được phát trực tuyến."}]}', 'course', 1, 'b2-online-learning', 'study', 30)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
