INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'wancha'), 'The Cinema in My Pocket', 'How streaming changed movies', 'B2', '{"title":"The Cinema in My Pocket","summary_vi":"Luyện nghe và đọc một bài tiểu luận cá nhân về việc các nền tảng phát trực tuyến thay đổi ngành điện ảnh và thói quen xem phim.","sentences":["As a teenager, I once queued for two hours to see a film that had already been out abroad for months.","Today the same film would be waiting on my phone before I finished my breakfast.","Streaming platforms have turned the entertainment industry upside down in barely fifteen years.","Studios that once relied on box office takings now compete for monthly subscriptions.","As a result, thousands of hours of content are made every year, and audiences are spoilt for choice.","This has opened doors for stories from outside Hollywood, such as Korean dramas and Spanish thrillers that found global fans overnight.","Directors enjoy bigger budgets and more creative freedom than they would have been given by a traditional studio.","On the other hand, the sheer volume makes it hard for quieter films to get noticed.","Shows are cancelled after one season if the algorithm decides they are not worth the gamble.","Cinemas have suffered too, although the best ones have survived by offering an experience that a sofa cannot match.","Personally, I binge-watch more than I would like to admit, and I rarely remember what I have seen.","Perhaps the real luxury today is not having more choice, but having the patience to choose well."],"sentences_vi":["Hồi còn là thiếu niên, tôi từng xếp hàng hai tiếng đồng hồ để xem một bộ phim đã chiếu ở nước ngoài từ mấy tháng trước.","Ngày nay, cũng bộ phim ấy sẽ nằm sẵn trong điện thoại của tôi trước khi tôi ăn xong bữa sáng.","Các nền tảng phát trực tuyến đã đảo lộn ngành giải trí chỉ trong chưa đầy mười lăm năm.","Các hãng phim từng sống nhờ doanh thu phòng vé nay phải cạnh tranh để có người đăng ký theo tháng.","Kết quả là mỗi năm có hàng nghìn giờ nội dung được sản xuất, và khán giả có quá nhiều thứ để lựa chọn.","Điều này đã mở ra cơ hội cho những câu chuyện ngoài Hollywood, như phim truyền hình Hàn Quốc và phim kinh dị Tây Ban Nha, vốn có người hâm mộ toàn cầu chỉ sau một đêm.","Các đạo diễn có kinh phí lớn hơn và tự do sáng tạo hơn so với những gì một hãng phim truyền thống sẽ cho họ.","Mặt khác, số lượng quá lớn khiến những bộ phim nhẹ nhàng khó được chú ý.","Các chương trình bị hủy sau một mùa nếu thuật toán cho rằng chúng không đáng để đánh cược.","Rạp chiếu phim cũng chịu thiệt hại, dù những rạp tốt nhất vẫn trụ lại được nhờ mang đến trải nghiệm mà chiếc ghế sofa không thể sánh bằng.","Cá nhân tôi cày phim nhiều hơn mức tôi muốn thừa nhận, và hiếm khi nhớ mình đã xem những gì.","Có lẽ thứ xa xỉ thật sự ngày nay không phải là có nhiều lựa chọn hơn, mà là có đủ kiên nhẫn để chọn cho tốt."],"vocabulary":[{"word":"upside down","ipa":"/ˈʌpsaɪd daʊn/","pos":"adverb","meaning_vi":"đảo lộn hoàn toàn","example":"The pandemic turned our travel plans upside down.","example_vi":"Đại dịch đã đảo lộn các kế hoạch du lịch của chúng tôi."},{"word":"box office","ipa":"/bɑːks ˈɑːfɪs/","pos":"noun","meaning_vi":"doanh thu phòng vé","example":"The sequel was a huge success at the box office.","example_vi":"Phần tiếp theo đã thành công vang dội ở phòng vé."},{"word":"spoilt for choice","ipa":"/spɔɪlt fər tʃɔɪs/","pos":"idiom","meaning_vi":"có quá nhiều lựa chọn","example":"In this street food market, you are spoilt for choice.","example_vi":"Ở khu chợ ẩm thực đường phố này, bạn có quá nhiều món để lựa chọn."},{"word":"overnight","ipa":"/ˌoʊvərˈnaɪt/","pos":"adverb","meaning_vi":"chỉ sau một đêm, rất nhanh","example":"The young singer became famous overnight after one video.","example_vi":"Ca sĩ trẻ ấy nổi tiếng chỉ sau một đêm nhờ một đoạn video."},{"word":"creative freedom","ipa":"/kriˈeɪtɪv ˈfriːdəm/","pos":"noun","meaning_vi":"sự tự do sáng tạo","example":"The writer accepted the job because she was given complete creative freedom.","example_vi":"Nhà văn nhận lời làm công việc đó vì được trao toàn quyền sáng tạo."},{"word":"the sheer volume","ipa":"/ðə ʃɪr ˈvɑːljuːm/","pos":"phrase","meaning_vi":"khối lượng quá lớn","example":"The sheer volume of emails made it impossible to reply to everyone.","example_vi":"Số lượng email quá lớn khiến không thể trả lời hết mọi người."},{"word":"worth the gamble","ipa":"/wɜːrθ ðə ˈɡæmbəl/","pos":"phrase","meaning_vi":"đáng để mạo hiểm","example":"Opening a restaurant in a quiet town seemed worth the gamble.","example_vi":"Mở một nhà hàng ở thị trấn yên tĩnh dường như là một canh bạc đáng thử."}],"questions":[{"question":"What contrast does the writer open with?","options":["Cinema tickets were once cheaper","Waiting for films used to take much longer","Films used to be shorter","Teenagers watched fewer films"],"answer_index":1,"explanation_vi":"Trước đây phải xếp hàng và chờ hàng tháng, nay phim có sẵn ngay trên điện thoại."},{"question":"What benefit of streaming is described?","options":["Directors always earn more","Films are always better","Cinemas are more popular","Stories from outside Hollywood can reach a global audience"],"answer_index":3,"explanation_vi":"Phim Hàn và phim Tây Ban Nha tìm được khán giả toàn cầu nhờ các nền tảng."},{"question":"Why might quieter films struggle on streaming platforms?","options":["There is so much content that they are overlooked","Algorithms ban them","They are too expensive to make","Viewers dislike subtitles"],"answer_index":0,"explanation_vi":"Khối lượng nội dung khổng lồ khiến phim nhỏ khó được chú ý."},{"question":"What is the writer''s attitude in the final sentence?","options":["Excited about more choice","Angry at the platforms","Reflective, valuing patience over quantity","Uninterested in films"],"answer_index":2,"explanation_vi":"Tác giả suy ngẫm rằng điều quý giá là biết chọn lọc chứ không phải có thêm lựa chọn."}]}', 'course', 1, 'b2-streaming', 'fun', 31)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'wancha'), 'Sleep Is Not Wasted Time', 'Why we need more sleep', 'B2', '{"title":"Sleep Is Not Wasted Time","summary_vi":"Luyện nghe và đọc một bản tin khoa học về tầm quan trọng của giấc ngủ, cùng từ vựng về sức khỏe và thói quen sinh hoạt.","sentences":["Sleep used to be treated as wasted time, something ambitious people could cut down to make room for success.","Research over the past two decades has overturned that belief.","During deep sleep, the brain clears away waste products and moves the day''s memories into long-term storage.","Adults who regularly get less than six hours are more likely to develop heart disease and depression.","Even a single bad night can dull attention, much like drinking a couple of glasses of wine.","Teenagers are especially vulnerable, since their body clocks naturally shift later, yet school often starts at dawn.","Several districts that delayed the first bell by an hour reported better grades and fewer car accidents.","Dr Ana Ferreira, a sleep researcher in Lisbon, says people routinely underestimate how impaired they are.","\"If you need an alarm and a coffee to function, you are probably carrying a sleep debt,\" she explains.","Simple habits help: a consistent bedtime, a cool dark room and no screens for an hour beforehand.","None of this is glamorous, but it works better than any supplement on the market.","In short, a good night''s sleep is not a luxury; it is the foundation on which everything else is built."],"sentences_vi":["Trước đây, giấc ngủ bị coi là thời gian lãng phí, thứ mà những người có hoài bão có thể cắt giảm để dành chỗ cho thành công.","Các nghiên cứu trong hai thập kỷ qua đã lật ngược niềm tin ấy.","Trong giấc ngủ sâu, não bộ dọn dẹp các chất thải và chuyển những ký ức trong ngày vào kho lưu trữ dài hạn.","Những người trưởng thành thường xuyên ngủ ít hơn sáu tiếng có nguy cơ mắc bệnh tim và trầm cảm cao hơn.","Chỉ một đêm ngủ tồi cũng có thể làm giảm sự tập trung, chẳng khác nào uống vài ly rượu vang.","Thanh thiếu niên đặc biệt dễ bị ảnh hưởng, vì đồng hồ sinh học của các em tự nhiên lùi về muộn hơn, vậy mà trường học thường bắt đầu từ tờ mờ sáng.","Một vài khu học chánh đã lùi giờ vào học thêm một tiếng và ghi nhận điểm số tốt hơn cùng ít tai nạn xe hơn.","Bác sĩ Ana Ferreira, một nhà nghiên cứu giấc ngủ ở Lisbon, cho biết người ta thường xuyên đánh giá thấp mức độ suy giảm của bản thân.","\"Nếu bạn cần chuông báo thức và một ly cà phê mới tỉnh táo, nhiều khả năng bạn đang mang một khoản nợ ngủ,\" bà giải thích.","Những thói quen đơn giản sẽ giúp ích: giờ đi ngủ đều đặn, một căn phòng mát và tối, và không dùng màn hình trong một tiếng trước khi ngủ.","Không điều nào trong số này hào nhoáng, nhưng nó hiệu quả hơn bất kỳ loại thực phẩm chức năng nào trên thị trường.","Tóm lại, một giấc ngủ ngon không phải là thứ xa xỉ; nó là nền móng để mọi thứ khác được xây dựng lên."],"vocabulary":[{"word":"cut down","ipa":"/kʌt daʊn/","pos":"phrasal verb","meaning_vi":"cắt giảm","example":"The doctor told him to cut down on salt and sugar.","example_vi":"Bác sĩ bảo anh ấy giảm ăn muối và đường."},{"word":"overturned","ipa":"/ˌoʊvərˈtɜːrnd/","pos":"verb","meaning_vi":"lật đổ, bác bỏ","example":"The new evidence overturned the court''s earlier decision.","example_vi":"Bằng chứng mới đã lật ngược quyết định trước đó của tòa án."},{"word":"vulnerable","ipa":"/ˈvʌlnərəbəl/","pos":"adjective","meaning_vi":"dễ bị tổn thương","example":"Elderly people are more vulnerable to extreme heat.","example_vi":"Người cao tuổi dễ bị tổn thương hơn trước thời tiết nóng cực đoan."},{"word":"body clocks","ipa":"/ˈbɑːdi klɑːks/","pos":"noun","meaning_vi":"đồng hồ sinh học","example":"Flying across time zones confuses our body clocks for days.","example_vi":"Bay qua nhiều múi giờ làm đồng hồ sinh học của chúng ta rối loạn trong nhiều ngày."},{"word":"underestimate","ipa":"/ˌʌndərˈɛstɪmeɪt/","pos":"verb","meaning_vi":"đánh giá thấp","example":"Never underestimate the power of a good night''s rest.","example_vi":"Đừng bao giờ đánh giá thấp sức mạnh của một giấc ngủ ngon."},{"word":"sleep debt","ipa":"/sliːp dɛt/","pos":"noun","meaning_vi":"nợ ngủ (thiếu ngủ tích lũy)","example":"A weekend lie-in cannot repay months of sleep debt.","example_vi":"Một buổi sáng cuối tuần ngủ nướng không thể trả hết nợ ngủ tích lũy nhiều tháng."},{"word":"in short","ipa":"/ɪn ʃɔːrt/","pos":"phrase","meaning_vi":"tóm lại","example":"The plan was costly and slow; in short, it was a mistake.","example_vi":"Kế hoạch vừa tốn kém vừa chậm chạp; tóm lại, đó là một sai lầm."}],"questions":[{"question":"What did research over the last two decades show?","options":["Sleep can be shortened without harm","Sleep is essential, not wasted time","Only teenagers need sleep","Coffee replaces sleep"],"answer_index":1,"explanation_vi":"Nghiên cứu đã bác bỏ quan niệm coi giấc ngủ là thời gian lãng phí."},{"question":"What happens in the brain during deep sleep?","options":["It stops working entirely","It forgets old skills","It stores memories and clears waste","It produces caffeine"],"answer_index":2,"explanation_vi":"Trong giấc ngủ sâu, não dọn chất thải và đưa ký ức vào kho lưu trữ dài hạn."},{"question":"Why are teenagers especially at risk?","options":["They dislike school","They sleep too much","They drink more wine","Their body clocks shift later but school starts early"],"answer_index":3,"explanation_vi":"Đồng hồ sinh học của thiếu niên lệch muộn trong khi giờ học bắt đầu rất sớm."},{"question":"What does Dr Ferreira imply about people who rely on alarms and coffee?","options":["They probably do not get enough sleep","They are healthier than average","They should sleep less","They have no sleep problems"],"answer_index":0,"explanation_vi":"Cô cho rằng cần báo thức và cà phê để tỉnh táo là dấu hiệu đang nợ giấc ngủ."}]}', 'course', 1, 'b2-sleep-science', 'health', 32)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'wancha'), 'Know Your Worth', 'Negotiating a salary', 'C1', '{"title":"Know Your Worth","summary_vi":"Luyện cách trình bày và thương lượng mức lương một cách tự tin, tinh tế bằng tiếng Anh.","sentences":["Most people dread the moment when an employer asks, \"So, what are you looking for?\"","Yet it is precisely at that point that your leverage is greatest, provided you have done your homework.","Never walk into a negotiation without a clear sense of the going rate for your role and city.","Should the first figure they offer fall short, resist the urge to accept it out of sheer relief.","Anchoring is powerful: whoever names a number first tends to shape the entire conversation that follows.","Rather than demanding more, frame your request around the value you will bring to the team.","It is not the salary alone that matters, but the whole package, including bonuses, flexibility and training budgets.","If the company genuinely cannot stretch its budget, you can still negotiate a formal review in six months.","In Hanoi and Singapore alike, hiring managers expect some back-and-forth, and a polite counteroffer rarely offends anyone.","What truly undermines candidates is not asking too much, but apologising for asking at all.","Stay composed, let silence work in your favour, and be prepared to walk away if the terms are unreasonable.","Remember that a well-handled negotiation signals precisely the confidence employers hope to see in their future colleagues."],"sentences_vi":["Hầu hết mọi người đều ngại khoảnh khắc nhà tuyển dụng hỏi: \"Vậy anh/chị đang mong muốn điều gì?\"","Thế nhưng chính vào lúc đó, lợi thế của bạn lại lớn nhất, miễn là bạn đã chuẩn bị kỹ.","Đừng bao giờ bước vào một cuộc thương lượng khi chưa nắm rõ mức lương phổ biến cho vị trí của bạn tại thành phố đó.","Nếu mức đầu tiên họ đưa ra còn thấp, đừng vì quá nhẹ nhõm mà vội nhận ngay.","Hiệu ứng neo giá rất mạnh: ai nêu con số trước thường định hình cả cuộc trao đổi sau đó.","Thay vì đòi hỏi nhiều hơn, hãy trình bày đề nghị của bạn xoay quanh giá trị bạn sẽ mang lại cho đội nhóm.","Điều quan trọng không chỉ là mức lương, mà là cả gói đãi ngộ, bao gồm thưởng, sự linh hoạt và ngân sách đào tạo.","Nếu công ty thực sự không thể tăng ngân sách, bạn vẫn có thể thương lượng một buổi đánh giá chính thức sau sáu tháng.","Ở Hanoi cũng như Singapore, các nhà quản lý tuyển dụng đều mong có qua có lại đôi chút, và một lời đề nghị lại lịch sự hiếm khi làm ai phật ý.","Điều thực sự làm ứng viên mất điểm không phải là đòi quá nhiều, mà là xin lỗi vì đã dám đòi.","Hãy giữ bình tĩnh, để sự im lặng làm việc có lợi cho mình, và sẵn sàng rút lui nếu các điều khoản không hợp lý.","Hãy nhớ rằng một cuộc thương lượng khéo léo chính là dấu hiệu của sự tự tin mà nhà tuyển dụng mong thấy ở các đồng nghiệp tương lai."],"vocabulary":[{"word":"leverage","ipa":"/ˈlɛvərɪdʒ/","pos":"noun","meaning_vi":"lợi thế để thương lượng","example":"Having a competing job offer gave her real leverage during the talks.","example_vi":"Có trong tay một lời mời làm việc khác đã mang lại cho cô ấy lợi thế thực sự trong cuộc đàm phán."},{"word":"going rate","ipa":"/ˈɡoʊɪŋ reɪt/","pos":"noun","meaning_vi":"mức giá/lương phổ biến hiện hành","example":"Freelance designers in this city charge the going rate of about fifty dollars an hour.","example_vi":"Các nhà thiết kế tự do ở thành phố này tính mức giá phổ biến khoảng năm mươi đô la một giờ."},{"word":"fall short","ipa":"/fɔl ʃɔrt/","pos":"phrase","meaning_vi":"không đạt kỳ vọng","example":"If the proposal should fall short of our expectations, we will ask for revisions.","example_vi":"Nếu đề xuất không đạt kỳ vọng của chúng tôi, chúng tôi sẽ yêu cầu chỉnh sửa."},{"word":"anchoring","ipa":"/ˈæŋkərɪŋ/","pos":"noun","meaning_vi":"hiệu ứng neo giá","example":"Anchoring explains why the first price on a menu colours how expensive the rest seems.","example_vi":"Hiệu ứng neo giá giải thích vì sao giá đầu tiên trên thực đơn lại chi phối cảm giác về độ đắt của những món còn lại."},{"word":"counteroffer","ipa":"/ˈkaʊntərˌɔfər/","pos":"noun","meaning_vi":"đề nghị phản hồi lại","example":"After a short pause, the buyer made a counteroffer that was ten percent lower.","example_vi":"Sau một lúc im lặng, người mua đưa ra mức giá phản hồi thấp hơn mười phần trăm."},{"word":"back-and-forth","ipa":"/ˌbæk ən ˈfɔrθ/","pos":"noun","meaning_vi":"sự trao đổi qua lại","example":"After weeks of back-and-forth, the two firms finally signed the contract.","example_vi":"Sau nhiều tuần qua lại thương lượng, hai công ty cuối cùng cũng ký hợp đồng."},{"word":"walk away","ipa":"/wɔk əˈweɪ/","pos":"phrase","meaning_vi":"rút lui, từ chối thỏa thuận","example":"A good negotiator knows when to walk away from a deal that does not add up.","example_vi":"Một nhà đàm phán giỏi biết lúc nào nên rút khỏi một thỏa thuận không có lợi."}],"questions":[{"question":"What is the main purpose of the passage?","options":["To warn candidates against changing jobs","To offer practical advice on negotiating pay","To compare salaries in different countries","To criticise how employers hire"],"answer_index":1,"explanation_vi":"Bài viết đưa ra lời khuyên thực tế về cách thương lượng lương."},{"question":"According to the passage, why does anchoring matter?","options":["It makes employers feel more generous","It lets candidates avoid awkward silences","The first number named tends to shape the discussion","It guarantees a higher final salary"],"answer_index":2,"explanation_vi":"Người nêu con số đầu tiên thường định hướng cả cuộc trao đổi."},{"question":"What does the writer say damages a candidate''s position most?","options":["Asking for too much money","Arriving without a counteroffer","Staying silent during talks","Apologising for making a request"],"answer_index":3,"explanation_vi":"Tác giả cho rằng việc xin lỗi vì đã đề nghị mới là điều gây bất lợi nhất."},{"question":"What option is suggested if the budget cannot be increased?","options":["Negotiating a review after six months","Accepting the first offer gratefully","Asking for a longer probation period","Moving to a different city"],"answer_index":0,"explanation_vi":"Nếu ngân sách hạn chế, có thể thương lượng một cuộc xem xét lại sau sáu tháng."}]}', 'course', 1, 'c1-salary-negotiation', 'work', 33)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'wancha'), 'Who Answers to the Algorithm?', 'The ethics of artificial intelligence', 'C1', '{"title":"Who Answers to the Algorithm?","summary_vi":"Luyện đọc và thảo luận về các vấn đề đạo đức của trí tuệ nhân tạo với từ vựng học thuật.","sentences":["Artificial intelligence is no longer a distant promise; it already decides who gets a loan, an interview or a medical scan.","That reach raises an uncomfortable question: who is accountable when an algorithm gets it wrong?","Bias is the most cited concern, and with good reason, since models learn from data that reflects historical prejudice.","A hiring tool trained on past decisions may quietly penalise women, simply because fewer of them were hired before.","Transparency offers a partial remedy, yet many systems remain black boxes even to the engineers who built them.","Were companies required to explain automated decisions, public trust would arguably be easier to earn.","Privacy poses a separate dilemma, because the data that makes these tools useful is often collected without meaningful consent.","Others worry less about present harms than about the long-term erosion of human judgement and skills.","Regulation is therefore taking shape, though lawmakers struggle to keep pace with a technology that evolves almost monthly.","In Vietnam, as elsewhere, the debate is shifting from whether to adopt AI to how to govern it responsibly.","Ultimately, it is not the machines that hold values, but the people who design, deploy and oversee them."],"sentences_vi":["Trí tuệ nhân tạo không còn là một lời hứa xa vời; nó đã quyết định ai được vay tiền, được phỏng vấn hay được chụp chiếu y tế.","Tầm ảnh hưởng ấy đặt ra một câu hỏi khó chịu: ai sẽ chịu trách nhiệm khi thuật toán sai?","Thiên kiến là mối lo được nhắc đến nhiều nhất, và điều đó có lý do, vì các mô hình học từ dữ liệu phản ánh định kiến trong quá khứ.","Một công cụ tuyển dụng được huấn luyện trên các quyết định trước đây có thể âm thầm gây bất lợi cho phụ nữ, đơn giản vì trước kia họ được tuyển ít hơn.","Tính minh bạch là một phần lời giải, nhưng nhiều hệ thống vẫn là những chiếc hộp đen, ngay cả với các kỹ sư đã xây dựng nên chúng.","Nếu các công ty buộc phải giải thích những quyết định tự động, có lẽ lòng tin của công chúng sẽ dễ có được hơn.","Quyền riêng tư là một thế tiến thoái lưỡng nan khác, vì dữ liệu làm nên giá trị của các công cụ này thường được thu thập mà không có sự đồng ý đúng nghĩa.","Một số người lo ngại không phải về những tác hại hiện tại mà về việc khả năng phán đoán và kỹ năng của con người sẽ dần bị mai một về lâu dài.","Vì vậy, các quy định đang dần hình thành, dù các nhà làm luật khó theo kịp một công nghệ gần như tháng nào cũng đổi thay.","Ở Vietnam cũng như nhiều nơi khác, cuộc tranh luận đang chuyển từ việc có nên áp dụng AI hay không sang việc quản lý nó một cách có trách nhiệm như thế nào.","Suy cho cùng, không phải máy móc mang giá trị, mà là những con người thiết kế, triển khai và giám sát chúng."],"vocabulary":[{"word":"accountable","ipa":"/əˈkaʊntəbəl/","pos":"adjective","meaning_vi":"phải chịu trách nhiệm","example":"Managers must be held accountable for the decisions their teams make.","example_vi":"Các nhà quản lý phải chịu trách nhiệm về những quyết định mà nhóm của mình đưa ra."},{"word":"bias","ipa":"/ˈbaɪəs/","pos":"noun","meaning_vi":"thiên kiến, sự thiên vị","example":"The study found a clear bias against older applicants.","example_vi":"Nghiên cứu cho thấy có sự thiên vị rõ rệt đối với các ứng viên lớn tuổi."},{"word":"black boxes","ipa":"/blæk ˈbɑksəz/","pos":"noun","meaning_vi":"hệ thống \"hộp đen\" khó giải thích","example":"Deep neural networks are often described as black boxes because their reasoning is hidden.","example_vi":"Mạng nơ-ron sâu thường được gọi là hộp đen vì cách chúng suy luận bị che giấu."},{"word":"meaningful consent","ipa":"/ˈminɪŋfəl kənˈsɛnt/","pos":"noun","meaning_vi":"sự đồng ý có hiểu biết thực sự","example":"Clicking \"accept\" on a thirty-page policy hardly amounts to meaningful consent.","example_vi":"Bấm \"đồng ý\" với một bản chính sách dài ba mươi trang khó có thể coi là sự đồng thuận thực sự."},{"word":"erosion","ipa":"/ɪˈroʊʒən/","pos":"noun","meaning_vi":"sự xói mòn","example":"Critics fear the erosion of trust in the news media.","example_vi":"Các nhà phê bình lo ngại lòng tin vào truyền thông tin tức đang dần xói mòn."},{"word":"keep pace with","ipa":"/kip peɪs wɪð/","pos":"phrase","meaning_vi":"theo kịp","example":"Schools are struggling to keep pace with the speed of technological change.","example_vi":"Các trường học đang chật vật để theo kịp tốc độ thay đổi của công nghệ."},{"word":"deploy","ipa":"/dɪˈplɔɪ/","pos":"verb","meaning_vi":"triển khai, đưa vào sử dụng","example":"The bank plans to deploy the new fraud-detection system next spring.","example_vi":"Ngân hàng dự định triển khai hệ thống phát hiện gian lận mới vào mùa xuân tới."}],"questions":[{"question":"Why does the writer say bias is a serious concern in AI?","options":["Engineers deliberately introduce it","Models learn from data that carries past prejudice","Users rarely read the results","It only affects financial services"],"answer_index":1,"explanation_vi":"Mô hình học từ dữ liệu phản ánh định kiến trong quá khứ."},{"question":"What does the hiring-tool example illustrate?","options":["A system copying historical unfairness","A tool that is too expensive to run","Women refusing to apply for jobs","Faster recruitment for large firms"],"answer_index":0,"explanation_vi":"Ví dụ cho thấy hệ thống lặp lại sự bất công vốn có trong dữ liệu cũ."},{"question":"What is the writer''s attitude towards regulation?","options":["Dismissive of its value","Certain that it will fail","Cautiously accepting but aware of its limits","Strongly opposed to new laws"],"answer_index":2,"explanation_vi":"Tác giả ghi nhận quy định đang hình thành nhưng thừa nhận khó theo kịp công nghệ."},{"question":"What is the main message of the final sentence?","options":["Machines will eventually develop values","Governments should ban AI","Companies are not responsible for software","Human beings remain responsible for AI"],"answer_index":3,"explanation_vi":"Câu cuối nhấn mạnh con người mới là bên chịu trách nhiệm về AI."}]}', 'course', 1, 'c1-ai-ethics', 'tech', 34)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'wancha'), 'Concrete Meets Canopy', 'Designing greener cities', 'C1', '{"title":"Concrete Meets Canopy","summary_vi":"Luyện đọc bài phóng sự về thiết kế đô thị xanh với các cụm từ nâng cao về môi trường.","sentences":["Walk through Singapore''s Gardens by the Bay and it becomes obvious that concrete and nature need not be enemies.","Cities occupy a small fraction of the planet''s land, yet they account for most of its energy consumption.","That imbalance is why planners are now rethinking streets, rooftops and even the humble pavement.","Green roofs absorb rainwater, insulate buildings and, perhaps most importantly, cool the air around them.","Cities like Copenhagen have gone further, redesigning entire districts so that heavy downpours drain into parks rather than basements.","Ho Chi Minh City, with its chronic flooding and punishing summers, has much to gain from such measures.","It is not enough, however, to plant trees and call the job done.","Without maintenance and thoughtful species selection, new greenery can wither, wasting both money and public goodwill.","Transport matters just as much; the more people cycle, walk or ride trains, the less smog settles over the skyline.","Critics warn that greening can trigger gentrification, pushing out the very residents it was meant to serve.","Addressing that risk requires affordable housing policies to be woven into the design from the outset.","A truly sustainable city, in other words, is one that is liveable for everyone, not merely photogenic."],"sentences_vi":["Hãy dạo bước qua Gardens by the Bay của Singapore, bạn sẽ thấy rõ bê tông và thiên nhiên không nhất thiết là kẻ thù của nhau.","Các thành phố chỉ chiếm một phần nhỏ diện tích đất của hành tinh, nhưng lại tiêu thụ phần lớn năng lượng của nó.","Sự mất cân đối đó là lý do các nhà quy hoạch đang suy nghĩ lại về đường phố, mái nhà và cả những vỉa hè bình thường.","Mái nhà xanh hấp thụ nước mưa, cách nhiệt cho công trình và, có lẽ quan trọng nhất, làm mát không khí xung quanh.","Những thành phố như Copenhagen còn đi xa hơn, thiết kế lại cả khu vực để nước từ những trận mưa lớn chảy vào công viên thay vì tràn xuống tầng hầm.","Ho Chi Minh City, với tình trạng ngập lụt triền miên và những mùa hè oi ả, có rất nhiều điều để hưởng lợi từ các biện pháp như vậy.","Tuy nhiên, chỉ trồng cây rồi coi như xong việc thì chưa đủ.","Nếu thiếu việc chăm sóc và chọn loài cây phù hợp, mảng xanh mới có thể héo úa, lãng phí cả tiền bạc lẫn thiện cảm của người dân.","Giao thông cũng quan trọng không kém: càng nhiều người đi xe đạp, đi bộ hay đi tàu, khói bụi phủ trên bầu trời thành phố càng ít.","Các nhà phê bình cảnh báo rằng việc xanh hóa có thể kéo theo quá trình tư sản hóa đô thị, đẩy chính những cư dân mà nó phục vụ ra khỏi khu vực.","Để giải quyết rủi ro này, các chính sách nhà ở giá rẻ cần được lồng ghép vào thiết kế ngay từ đầu.","Nói cách khác, một thành phố bền vững thực sự là nơi đáng sống cho mọi người, chứ không chỉ đẹp để chụp ảnh."],"vocabulary":[{"word":"account for","ipa":"/əˈkaʊnt fɔr/","pos":"phrase","meaning_vi":"chiếm (một tỷ lệ)","example":"Cars account for nearly half of the city''s air pollution.","example_vi":"Xe hơi gây ra gần một nửa tình trạng ô nhiễm không khí của thành phố."},{"word":"insulate","ipa":"/ˈɪnsəˌleɪt/","pos":"verb","meaning_vi":"cách nhiệt","example":"Thick walls insulate the old house against the summer heat.","example_vi":"Những bức tường dày giúp ngôi nhà cổ cách nhiệt khỏi cái nóng mùa hè."},{"word":"downpours","ipa":"/ˈdaʊnˌpɔrz/","pos":"noun","meaning_vi":"những trận mưa như trút","example":"Sudden downpours turned the streets into rivers within minutes.","example_vi":"Những trận mưa lớn bất chợt biến các con phố thành sông chỉ trong vài phút."},{"word":"chronic","ipa":"/ˈkrɑnɪk/","pos":"adjective","meaning_vi":"kinh niên, kéo dài","example":"Chronic traffic congestion costs the economy millions every year.","example_vi":"Tình trạng kẹt xe triền miên khiến nền kinh tế thiệt hại hàng triệu mỗi năm."},{"word":"wither","ipa":"/ˈwɪðər/","pos":"verb","meaning_vi":"héo úa, tàn lụi","example":"Without regular watering, the young saplings will wither.","example_vi":"Nếu không được tưới nước thường xuyên, những cây non sẽ héo úa."},{"word":"gentrification","ipa":"/ˌdʒɛntrəfɪˈkeɪʃən/","pos":"noun","meaning_vi":"hiện tượng tầng lớp giàu đẩy giá khiến dân cũ phải rời đi","example":"Rapid gentrification has made the old quarter unaffordable for many families.","example_vi":"Quá trình tư sản hóa đô thị nhanh chóng đã khiến khu phố cổ trở nên quá đắt đỏ với nhiều gia đình."},{"word":"from the outset","ipa":"/frəm ði ˈaʊtˌsɛt/","pos":"phrase","meaning_vi":"ngay từ đầu","example":"The architect made it clear from the outset that the budget was tight.","example_vi":"Ngay từ đầu, kiến trúc sư đã nói rõ rằng ngân sách rất eo hẹp."}],"questions":[{"question":"What contrast does the second sentence draw?","options":["City size versus population","Small land area versus large energy use","Old buildings versus new ones","Rich cities versus poor ones"],"answer_index":1,"explanation_vi":"Thành phố chiếm ít đất nhưng tiêu thụ phần lớn năng lượng."},{"question":"Why does the writer mention Ho Chi Minh City?","options":["To criticise its transport system","To praise its parks","To show it could benefit from green measures","To compare it with Copenhagen''s budget"],"answer_index":2,"explanation_vi":"Thành phố này chịu ngập và nóng nên được lợi từ các giải pháp xanh."},{"question":"What risk of greening do critics identify?","options":["Higher smog levels","Fewer cyclists","Wasted rainwater","Pushing out existing residents"],"answer_index":3,"explanation_vi":"Các nhà phê bình lo việc làm xanh gây gentrification, đẩy dân cũ đi."},{"question":"What is implied by the last sentence?","options":["Sustainability must include social fairness","Beauty matters more than function","Only wealthy cities can go green","Photogenic cities attract more tourists"],"answer_index":0,"explanation_vi":"Thành phố bền vững phải dễ sống cho mọi người, không chỉ đẹp."}]}', 'course', 1, 'c1-green-cities', 'nature', 35)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;
INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'wancha'), 'The Mind''s Shortcuts', 'Cognitive biases in everyday decisions', 'C1', '{"title":"The Mind''s Shortcuts","summary_vi":"Luyện đọc bài suy ngẫm về các thiên kiến nhận thức ảnh hưởng đến quyết định hằng ngày.","sentences":["We like to imagine that our decisions flow from careful reasoning, but the mind prefers shortcuts.","Psychologists call these shortcuts heuristics, and while they save time, they also leave us prone to systematic error.","Take confirmation bias: once we hold a belief, we instinctively seek out evidence that supports it.","Rarely do we notice how selectively we read the news, or whom we choose to listen to.","Then there is the sunk cost fallacy, which keeps people in failing projects simply because they have already invested so much.","I once sat through an entire dreadful film for precisely that reason, having paid for the ticket.","Anchoring is subtler still, since an arbitrary first number can distort every estimate that follows.","Knowing about these traps does not make us immune; if anything, it can breed overconfidence.","What helps is slowing down, particularly when the stakes are high and emotions are running hot.","Asking a trusted friend to challenge your reasoning, or writing down your assumptions, can expose blind spots.","We will never be perfectly rational, but we can learn to catch ourselves in the act."],"sentences_vi":["Chúng ta thích nghĩ rằng quyết định của mình xuất phát từ suy luận cẩn trọng, nhưng bộ não lại thích đi đường tắt.","Các nhà tâm lý học gọi những lối tắt này là heuristics; chúng tiết kiệm thời gian nhưng cũng khiến ta dễ mắc lỗi có tính hệ thống.","Hãy lấy thiên kiến xác nhận làm ví dụ: một khi đã tin điều gì, ta sẽ theo bản năng tìm kiếm bằng chứng ủng hộ nó.","Hiếm khi ta nhận ra mình chọn lọc đến mức nào khi đọc tin tức, hay khi chọn người để lắng nghe.","Rồi còn có ngụy biện chi phí chìm, thứ khiến người ta ở lại những dự án đang thất bại chỉ vì đã bỏ ra quá nhiều.","Có lần tôi ngồi xem hết một bộ phim dở tệ cũng vì chính lý do đó, vì đã mua vé rồi.","Hiệu ứng neo giá còn tinh vi hơn, vì một con số đầu tiên tùy tiện cũng có thể làm sai lệch mọi ước tính sau đó.","Biết về những cái bẫy này không giúp ta miễn nhiễm; thậm chí, nó còn có thể sinh ra sự tự tin thái quá.","Điều giúp ích là chậm lại, nhất là khi rủi ro cao và cảm xúc đang bốc lên.","Nhờ một người bạn đáng tin thử phản biện lập luận của bạn, hoặc viết ra các giả định của mình, có thể giúp lộ ra những điểm mù.","Chúng ta sẽ không bao giờ hoàn toàn lý trí, nhưng có thể học cách bắt quả tang chính mình."],"vocabulary":[{"word":"prone to","ipa":"/proʊn tu/","pos":"adjective","meaning_vi":"dễ bị, có xu hướng","example":"Tired drivers are more prone to making serious mistakes.","example_vi":"Những tài xế mệt mỏi dễ mắc sai lầm nghiêm trọng hơn."},{"word":"confirmation bias","ipa":"/ˌkɑnfərˈmeɪʃən ˈbaɪəs/","pos":"noun","meaning_vi":"thiên kiến xác nhận","example":"Confirmation bias leads us to share only the articles that agree with us.","example_vi":"Thiên kiến xác nhận khiến chúng ta chỉ chia sẻ những bài báo đồng tình với mình."},{"word":"sunk cost fallacy","ipa":"/sʌŋk kɔst ˈfæləsi/","pos":"noun","meaning_vi":"ngụy biện chi phí chìm","example":"Staying in a bad investment because of past losses is the sunk cost fallacy in action.","example_vi":"Cố giữ một khoản đầu tư tồi vì những khoản lỗ trước đó chính là ngụy biện chi phí chìm."},{"word":"arbitrary","ipa":"/ˈɑrbəˌtrɛri/","pos":"adjective","meaning_vi":"tùy tiện, ngẫu nhiên","example":"The deadline seemed arbitrary, since nobody could explain how it was chosen.","example_vi":"Thời hạn đó có vẻ tùy tiện, vì không ai giải thích được nó được chọn như thế nào."},{"word":"breed","ipa":"/brid/","pos":"verb","meaning_vi":"gây ra, nuôi dưỡng","example":"Constant praise can breed complacency in a young team.","example_vi":"Lời khen liên tục có thể nuôi dưỡng sự tự mãn trong một đội ngũ trẻ."},{"word":"the stakes are high","ipa":"/ðə steɪks ɑr haɪ/","pos":"idiom","meaning_vi":"rủi ro/được mất rất lớn","example":"Before a final exam, the stakes are high and even small errors feel enormous.","example_vi":"Trước kỳ thi cuối kỳ, áp lực rất lớn và ngay cả những lỗi nhỏ cũng thấy nghiêm trọng."},{"word":"blind spots","ipa":"/blaɪnd spɑts/","pos":"noun","meaning_vi":"điểm mù, thiếu sót không nhận ra","example":"Honest feedback helps leaders identify their blind spots.","example_vi":"Những phản hồi thẳng thắn giúp người lãnh đạo nhận ra điểm mù của mình."}],"questions":[{"question":"What does the writer suggest about heuristics?","options":["They are always harmful","They save time but can mislead us","They only affect experts","They have been scientifically disproved"],"answer_index":1,"explanation_vi":"Heuristics tiết kiệm thời gian nhưng khiến ta dễ mắc lỗi có hệ thống."},{"question":"Why does the writer mention watching a dreadful film?","options":["To recommend a particular movie","To criticise cinema ticket prices","To illustrate a bias with a personal example","To show how little they value money"],"answer_index":2,"explanation_vi":"Đó là ví dụ cá nhân minh họa cho ngụy biện chi phí chìm."},{"question":"What ironic point is made about knowing these biases?","options":["Awareness can make us overconfident","Awareness eliminates all errors","Biases only affect the uninformed","Awareness makes decisions slower"],"answer_index":0,"explanation_vi":"Biết về thiên kiến không giúp miễn nhiễm, thậm chí có thể gây tự tin quá mức."},{"question":"What is the tone of the final sentence?","options":["Angry and accusing","Doubtful and confused","Mocking and sarcastic","Realistic and gently hopeful"],"answer_index":3,"explanation_vi":"Câu cuối thừa nhận sự không hoàn hảo nhưng vẫn lạc quan nhẹ nhàng."}]}', 'course', 1, 'c1-cognitive-bias', 'people', 36)
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
