INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'wancha'), 'Butterflies in Formation', 'Speaking in public with confidence', 'C1', '{"title":"Butterflies in Formation","summary_vi":"Luyện nghe và nói theo một bài phát biểu về cách tự tin khi nói trước đám đông.","sentences":["Good evening, everyone, and thank you for coming; I promise to keep my nerves in check.","Let me begin with a confession: for years, I would rather have done almost anything than speak in public.","My palms would sweat, my voice would tremble, and my carefully prepared words would vanish.","What changed was not that the fear disappeared, but that I learned to reinterpret it.","Those butterflies are simply your body gearing up for a challenge, and a little adrenaline sharpens focus.","Preparation matters, of course, yet over-rehearsing every word can make you sound stilted and robotic.","I now build my talks around three key ideas, which gives me something solid to fall back on.","Pausing is the most underrated skill; a well-placed silence lets your point sink in.","Equally important is eye contact, because speaking to individuals feels far less daunting than addressing a crowd.","Should you stumble, don''t panic; audiences are remarkably forgiving when a speaker simply carries on.","Above all, remember that people are not there to judge you, but to hear what you have to say.","Thank you; now, I''d be glad to take your questions."],"sentences_vi":["Chào mọi người, cảm ơn vì đã đến; tôi hứa sẽ giữ cho mình bình tĩnh.","Trước hết tôi xin thú nhận: suốt nhiều năm, tôi thà làm bất cứ việc gì còn hơn phải nói trước đám đông.","Lòng bàn tay tôi toát mồ hôi, giọng run lên, và những lời tôi đã chuẩn bị kỹ lưỡng bỗng biến mất.","Điều thay đổi không phải là nỗi sợ biến mất, mà là tôi học được cách nhìn nhận nó theo hướng khác.","Cảm giác bồn chồn đó chỉ là cơ thể bạn đang chuẩn bị cho một thử thách, và một chút adrenaline giúp bạn tập trung hơn.","Tất nhiên, chuẩn bị là quan trọng, nhưng luyện tập từng chữ quá mức có thể khiến bạn nói gượng gạo và máy móc.","Giờ tôi xây dựng bài nói quanh ba ý chính, nhờ vậy tôi có điểm tựa vững chắc để quay về.","Biết ngắt nghỉ là kỹ năng bị đánh giá thấp nhất; một khoảng lặng đúng lúc giúp ý của bạn thấm sâu.","Giao tiếp bằng mắt cũng quan trọng không kém, vì nói với từng người đỡ đáng sợ hơn nhiều so với nói trước cả đám đông.","Nếu bạn vấp, đừng hoảng; khán giả rất bao dung khi diễn giả cứ bình thản nói tiếp.","Trên hết, hãy nhớ rằng mọi người đến đây không phải để phán xét bạn, mà để nghe điều bạn muốn nói.","Cảm ơn mọi người; giờ tôi rất sẵn lòng trả lời các câu hỏi của quý vị."],"vocabulary":[{"word":"in check","ipa":"/ɪn tʃɛk/","pos":"phrase","meaning_vi":"được kiểm soát","example":"She kept her anger in check throughout the heated meeting.","example_vi":"Cô ấy kiềm chế được cơn giận suốt cuộc họp căng thẳng."},{"word":"gearing up for","ipa":"/ˈɡɪrɪŋ ʌp fɔr/","pos":"phrase","meaning_vi":"chuẩn bị cho","example":"The whole team is gearing up for next week''s product launch.","example_vi":"Cả nhóm đang chuẩn bị cho đợt ra mắt sản phẩm vào tuần tới."},{"word":"stilted","ipa":"/ˈstɪltɪd/","pos":"adjective","meaning_vi":"gượng gạo, thiếu tự nhiên","example":"His stilted greeting made the atmosphere even more awkward.","example_vi":"Lời chào gượng gạo của anh ấy khiến bầu không khí càng thêm ngượng ngập."},{"word":"fall back on","ipa":"/fɔl bæk ɑn/","pos":"phrase","meaning_vi":"dựa vào khi cần","example":"Having savings gave her something to fall back on when the business struggled.","example_vi":"Có khoản tiết kiệm giúp cô ấy có chỗ dựa khi việc kinh doanh gặp khó khăn."},{"word":"sink in","ipa":"/sɪŋk ɪn/","pos":"phrase","meaning_vi":"được thấm, hiểu dần","example":"It took a few days for the news of the promotion to sink in.","example_vi":"Phải mất vài ngày thì tin được thăng chức mới thấm vào đầu cô ấy."},{"word":"daunting","ipa":"/ˈdɔntɪŋ/","pos":"adjective","meaning_vi":"khiến nản lòng, đáng sợ","example":"Starting a new career at forty can feel daunting.","example_vi":"Bắt đầu một sự nghiệp mới ở tuổi bốn mươi có thể khiến người ta thấy chùn bước."},{"word":"underrated","ipa":"/ˌʌndərˈreɪtɪd/","pos":"adjective","meaning_vi":"bị đánh giá thấp","example":"Listening is an underrated skill in any leadership role.","example_vi":"Biết lắng nghe là một kỹ năng bị đánh giá thấp ở bất kỳ vai trò lãnh đạo nào."}],"questions":[{"question":"What kind of text is this passage most likely to be?","options":["A written complaint","A spoken talk to an audience","A newspaper report","A set of instructions"],"answer_index":1,"explanation_vi":"Lời chào, cảm ơn và mời đặt câu hỏi cho thấy đây là bài nói trước khán giả."},{"question":"How did the speaker''s attitude to fear change?","options":["She stopped feeling any fear","She avoided all speaking events","She learned to see it as useful energy","She relied entirely on notes"],"answer_index":2,"explanation_vi":"Cô học cách nhìn nỗi sợ như năng lượng hữu ích chứ không xóa bỏ nó."},{"question":"Why does the speaker warn against over-rehearsing?","options":["It wastes too much time","It makes the audience bored","It causes physical illness","It can make a talk sound unnatural"],"answer_index":3,"explanation_vi":"Tập quá kỹ từng chữ khiến bài nói nghe gượng gạo, như người máy."},{"question":"What does the speaker say about audiences?","options":["They are forgiving if you carry on after a mistake","They notice every error","They prefer very short talks","They judge speakers harshly"],"answer_index":0,"explanation_vi":"Khán giả khá bao dung khi diễn giả vẫn tiếp tục sau khi vấp."}]}', 'course', 1, 'c1-public-speaking', 'people', 37)
