INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'wancha'), 'The Price of a Glance', 'The attention economy', 'C1', '{"title":"The Price of a Glance","summary_vi":"Luyện đọc bài luận về nền kinh tế chú ý và cách các nền tảng thu hút thời gian của chúng ta.","sentences":["If a service is free, the old saying goes, then you are the product.","Nowhere is that truer than in the attention economy, where your time and focus are the scarce currency.","Platforms compete fiercely to hold your gaze, and they have engineered features to do precisely that.","Endless scrolling, autoplay and notification badges are not accidents; they are carefully tested to keep you coming back.","The consequences are subtle but cumulative, as fragmented attention makes sustained, deep thinking harder to achieve.","Many Vietnamese teenagers now spend hours on short videos, often without recalling what they watched.","It would be unfair, though, to cast technology as the sole villain.","These tools connect families across oceans, democratise information and give small businesses a global stage.","The real issue is design that profits from compulsion rather than genuine value.","Some users are fighting back by switching off notifications, setting screen limits or reclaiming whole evenings offline.","Regulators, meanwhile, are asking whether manipulative design should face the same scrutiny as misleading advertising.","Until incentives change, the burden will keep falling on individuals to guard their own attention."],"sentences_vi":["Có câu nói xưa rằng nếu một dịch vụ miễn phí thì chính bạn là sản phẩm.","Không đâu đúng hơn trong nền kinh tế chú ý, nơi thời gian và sự tập trung của bạn là thứ tiền tệ khan hiếm.","Các nền tảng cạnh tranh quyết liệt để giữ ánh nhìn của bạn, và họ đã thiết kế những tính năng để làm đúng việc đó.","Cuộn trang bất tận, tự động phát video và các biểu tượng thông báo không phải ngẫu nhiên; chúng được thử nghiệm kỹ lưỡng để khiến bạn quay lại mãi.","Hậu quả tuy âm thầm nhưng tích tụ dần, khi sự chú ý bị phân mảnh khiến việc suy nghĩ sâu và bền bỉ trở nên khó khăn hơn.","Nhiều thanh thiếu niên Vietnam giờ dành hàng giờ xem video ngắn mà thường không nhớ mình đã xem gì.","Tuy nhiên, sẽ không công bằng nếu coi công nghệ là kẻ xấu duy nhất.","Những công cụ này kết nối các gia đình ở hai bên đại dương, đại chúng hóa thông tin và mang đến cho doanh nghiệp nhỏ một sân khấu toàn cầu.","Vấn đề thực sự là kiểu thiết kế kiếm lợi từ sự ép buộc thay vì giá trị đích thực.","Một số người dùng đang phản kháng bằng cách tắt thông báo, đặt giới hạn thời gian dùng màn hình hoặc giành lại cả buổi tối để không dùng mạng.","Trong khi đó, các cơ quan quản lý đang đặt câu hỏi liệu thiết kế mang tính thao túng có nên bị giám sát nghiêm ngặt như quảng cáo gây hiểu lầm hay không.","Cho đến khi các động cơ lợi ích thay đổi, gánh nặng bảo vệ sự chú ý của mình sẽ vẫn đè lên vai mỗi cá nhân."],"vocabulary":[{"word":"scarce","ipa":"/skɛrs/","pos":"adjective","meaning_vi":"khan hiếm","example":"Fresh water is becoming scarce in many coastal regions.","example_vi":"Nước ngọt đang trở nên khan hiếm ở nhiều vùng ven biển."},{"word":"engineered","ipa":"/ˌɛndʒəˈnɪrd/","pos":"verb","meaning_vi":"được thiết kế có chủ đích","example":"The snack was engineered to be impossible to stop eating.","example_vi":"Món ăn vặt này được thiết kế để khiến người ta không thể ngừng ăn."},{"word":"cumulative","ipa":"/ˈkjumjələtɪv/","pos":"adjective","meaning_vi":"tích lũy dần","example":"The cumulative effect of poor sleep is hard to ignore.","example_vi":"Tác động tích lũy của việc thiếu ngủ thật khó mà phớt lờ."},{"word":"fragmented","ipa":"/ˈfræɡˌmɛntɪd/","pos":"adjective","meaning_vi":"bị chia nhỏ, rời rạc","example":"A fragmented schedule left her no time for deep work.","example_vi":"Lịch trình rời rạc khiến cô ấy không còn thời gian cho công việc đòi hỏi tập trung sâu."},{"word":"democratise","ipa":"/dɪˈmɑkrəˌtaɪz/","pos":"verb","meaning_vi":"phổ cập cho mọi người","example":"Open courses aim to democratise access to higher education.","example_vi":"Các khóa học mở nhằm đại chúng hóa cơ hội tiếp cận giáo dục đại học."},{"word":"compulsion","ipa":"/kəmˈpʌlʃən/","pos":"noun","meaning_vi":"sự thôi thúc khó cưỡng","example":"He checked his phone out of compulsion rather than need.","example_vi":"Anh ấy kiểm tra điện thoại vì thói quen khó cưỡng chứ không phải vì cần thiết."},{"word":"scrutiny","ipa":"/ˈskrutəni/","pos":"noun","meaning_vi":"sự xem xét kỹ lưỡng","example":"The company''s accounts came under intense scrutiny after the scandal.","example_vi":"Sổ sách của công ty bị soi xét gắt gao sau vụ bê bối."}],"questions":[{"question":"What does \"you are the product\" suggest?","options":["Users receive free gifts","Companies profit from users'' attention and data","Free services are always high quality","Customers help design the product"],"answer_index":1,"explanation_vi":"Câu nói ngụ ý công ty kiếm lời từ sự chú ý và dữ liệu của người dùng."},{"question":"According to the writer, why are features like autoplay used?","options":["To save battery power","To teach users patience","To keep people returning and engaged","To reduce advertising costs"],"answer_index":2,"explanation_vi":"Các tính năng này được thử nghiệm kỹ để giữ người dùng quay lại."},{"question":"What is the writer''s overall view of technology?","options":["Entirely harmful","Largely irrelevant","Equally useful to all users","Beneficial but flawed by manipulative design"],"answer_index":3,"explanation_vi":"Tác giả công nhận lợi ích nhưng chỉ trích thiết kế thao túng."},{"question":"What does the final sentence imply?","options":["Individuals must protect their focus until incentives shift","Regulators have solved the problem","Teenagers are to blame","Platforms will soon change voluntarily"],"answer_index":0,"explanation_vi":"Chừng nào động cơ chưa đổi, cá nhân vẫn phải tự bảo vệ sự tập trung."}]}', 'course', 1, 'c1-attention-economy', 'tech', 38)
