INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'wancha'), 'More Than a Bowl', 'Food as cultural heritage', 'C1', '{"title":"More Than a Bowl","summary_vi":"Luyện đọc bài viết về ẩm thực như một di sản văn hóa với những cách diễn đạt tinh tế.","sentences":["A bowl of phở is never just a bowl of phở.","Behind its fragrant broth lies a century of migration, adaptation and fierce regional pride.","Food is among the most intimate ways a culture remembers itself, passed down not in books but in kitchens.","Grandmothers rarely measure ingredients; they rely on instinct, taste and a lifetime of repetition.","When such knowledge goes unrecorded, it can vanish within a single generation.","This is why UNESCO has begun recognising culinary traditions, from Neapolitan pizza to Korean kimchi-making, as intangible heritage.","Recognition, however, is a double-edged sword, since it may attract tourists who turn rituals into spectacle.","Street vendors in Huế, for instance, now compete with polished restaurants that serve imperial dishes in simplified form.","Purists argue that authenticity is being diluted, whereas others insist that cuisine has always evolved through borrowing.","Indeed, the bánh mì itself is a delicious product of colonial history and local ingenuity.","Perhaps the wisest approach is to document recipes faithfully while allowing cooks the freedom to improvise.","After all, a tradition that cannot breathe is merely a museum piece."],"sentences_vi":["Một tô phở không bao giờ chỉ là một tô phở.","Đằng sau nước dùng thơm lừng là cả một thế kỷ di cư, thích nghi và niềm tự hào vùng miền mãnh liệt.","Ẩm thực là một trong những cách gần gũi nhất để một nền văn hóa nhớ về chính mình, được truyền lại không phải trong sách vở mà trong những căn bếp.","Các bà các mẹ hiếm khi cân đo nguyên liệu; họ dựa vào bản năng, vị giác và cả một đời lặp đi lặp lại.","Khi những kiến thức như vậy không được ghi chép lại, chúng có thể biến mất chỉ trong một thế hệ.","Đó là lý do UNESCO bắt đầu công nhận các truyền thống ẩm thực, từ pizza Neapolitan đến nghề làm kimchi của Hàn Quốc, là di sản phi vật thể.","Tuy nhiên, sự công nhận là con dao hai lưỡi, vì nó có thể thu hút du khách biến các nghi lễ thành màn trình diễn.","Chẳng hạn, những người bán hàng rong ở Huế nay phải cạnh tranh với các nhà hàng sang trọng phục vụ món cung đình dưới dạng đơn giản hóa.","Những người theo chủ nghĩa thuần túy cho rằng tính nguyên bản đang bị pha loãng, trong khi những người khác khẳng định ẩm thực luôn phát triển nhờ vay mượn.","Thật vậy, bánh mì chính là một sản phẩm ngon lành của lịch sử thuộc địa và sự khéo léo sáng tạo của người địa phương.","Có lẽ cách tiếp cận khôn ngoan nhất là ghi chép công thức một cách trung thực, đồng thời để người nấu được tự do ứng biến.","Suy cho cùng, một truyền thống không thể thở được chỉ là một hiện vật trong viện bảo tàng."],"vocabulary":[{"word":"passed down","ipa":"/pæst daʊn/","pos":"phrase","meaning_vi":"được truyền lại","example":"The recipe has been passed down in her family for five generations.","example_vi":"Công thức này đã được truyền lại trong gia đình cô ấy qua năm thế hệ."},{"word":"intangible heritage","ipa":"/ɪnˈtændʒəbəl ˈhɛrɪtɪdʒ/","pos":"noun","meaning_vi":"di sản phi vật thể","example":"Folk songs are a precious form of intangible heritage.","example_vi":"Dân ca là một dạng di sản phi vật thể quý giá."},{"word":"double-edged sword","ipa":"/ˌdʌbəl ɛdʒd ˈsɔrd/","pos":"idiom","meaning_vi":"con dao hai lưỡi","example":"Fame can be a double-edged sword for young chefs.","example_vi":"Danh tiếng có thể là con dao hai lưỡi đối với các đầu bếp trẻ."},{"word":"authenticity","ipa":"/ˌɔθɛnˈtɪsəti/","pos":"noun","meaning_vi":"tính chân thực","example":"Diners often travel far in search of authenticity.","example_vi":"Thực khách thường đi rất xa để tìm kiếm hương vị nguyên bản."},{"word":"diluted","ipa":"/daɪˈlutɪd/","pos":"verb","meaning_vi":"bị pha loãng, làm yếu đi","example":"The original message was diluted by endless compromises.","example_vi":"Thông điệp ban đầu đã bị pha loãng bởi vô số lần thỏa hiệp."},{"word":"ingenuity","ipa":"/ˌɪndʒəˈnuəti/","pos":"noun","meaning_vi":"sự khéo léo, sáng tạo","example":"The village cooks showed great ingenuity during the food shortage.","example_vi":"Những người nấu ăn trong làng đã cho thấy sự khéo léo sáng tạo tuyệt vời trong lúc thiếu lương thực."},{"word":"improvise","ipa":"/ˈɪmprəˌvaɪz/","pos":"verb","meaning_vi":"ứng biến","example":"When the shop ran out of basil, she had to improvise with mint.","example_vi":"Khi cửa hàng hết húng quế, cô ấy phải ứng biến bằng bạc hà."}],"questions":[{"question":"What does the opening sentence suggest about phở?","options":["It is overrated abroad","It carries deep cultural meaning","It is too simple to describe","It was invented recently"],"answer_index":1,"explanation_vi":"Câu mở đầu ngụ ý phở mang nhiều ý nghĩa văn hóa hơn một món ăn."},{"question":"Why can culinary knowledge disappear so easily?","options":["Cooks refuse to share recipes","Ingredients are becoming rare","It is often unwritten and learned by instinct","Governments forbid traditional cooking"],"answer_index":2,"explanation_vi":"Kiến thức nấu ăn thường không được ghi lại mà truyền qua trực giác."},{"question":"Why is recognition called a double-edged sword?","options":["It makes recipes more expensive","It reduces the number of tourists","It encourages cooks to leave home","It can turn traditions into spectacle"],"answer_index":3,"explanation_vi":"Sự công nhận vừa bảo vệ vừa có thể biến nghi lễ thành màn trình diễn."},{"question":"What does the writer imply with the bánh mì example?","options":["Cuisine has long evolved through outside influences","Colonial food is inferior","Purists are always right","Sandwiches cannot be traditional"],"answer_index":0,"explanation_vi":"Bánh mì cho thấy ẩm thực vốn luôn tiến hóa nhờ vay mượn."}]}', 'course', 1, 'c1-food-heritage', 'food', 39)
