INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'wancha'), 'Beginners Forever', 'Learning for life', 'C1', '{"title":"Beginners Forever","summary_vi":"Luyện đọc bài suy ngẫm về việc học suốt đời và cách duy trì sự tò mò khi trưởng thành.","sentences":["For much of the twentieth century, education was imagined as a front-loaded affair: study first, work later.","That model is fast becoming obsolete.","Technologies shift so rapidly that skills acquired at twenty can look dated by thirty-five.","Lifelong learning, once a fashionable slogan, has therefore become a practical necessity.","Yet learning as an adult is not simply schooling repeated; it demands different habits.","Adults juggle jobs, families and fatigue, so motivation must come from relevance rather than obligation.","Many find that small, consistent effort outperforms occasional bursts of ambitious cramming.","Curiosity, moreover, is a muscle that strengthens with use and atrophies with neglect.","In Vietnam, evening classes, online courses and community libraries are widening access to people who missed formal opportunities.","Still, accessibility alone does not guarantee progress without the willingness to be a beginner again.","That humility, I would argue, is the hardest part and the most rewarding.","Those who embrace it tend to adapt more gracefully when the world inevitably changes around them."],"sentences_vi":["Trong phần lớn thế kỷ hai mươi, giáo dục được hình dung là chuyện dồn hết về đầu đời: học trước, làm việc sau.","Mô hình đó đang nhanh chóng trở nên lỗi thời.","Công nghệ thay đổi nhanh đến mức những kỹ năng học được ở tuổi hai mươi có thể trông lạc hậu khi bạn ba mươi lăm.","Vì vậy, học tập suốt đời, từng là một khẩu hiệu thời thượng, nay đã trở thành nhu cầu thiết thực.","Tuy nhiên, học khi đã trưởng thành không đơn giản là đi học lại; nó đòi hỏi những thói quen khác.","Người lớn phải xoay xở giữa công việc, gia đình và sự mệt mỏi, nên động lực phải đến từ sự thiết thực chứ không phải nghĩa vụ.","Nhiều người nhận ra rằng nỗ lực nhỏ nhưng đều đặn hiệu quả hơn những đợt học nhồi đầy tham vọng thỉnh thoảng mới có.","Hơn nữa, sự tò mò giống như một cơ bắp: càng dùng càng khỏe, càng bỏ bê càng teo đi.","Ở Vietnam, các lớp học buổi tối, khóa học trực tuyến và thư viện cộng đồng đang mở rộng cơ hội cho những người từng lỡ mất con đường học tập chính quy.","Dù vậy, chỉ có cơ hội tiếp cận thôi thì chưa đảm bảo tiến bộ nếu thiếu sự sẵn lòng làm người mới bắt đầu một lần nữa.","Theo tôi, sự khiêm tốn ấy là phần khó nhất và cũng đáng giá nhất.","Những ai đón nhận nó thường thích nghi nhẹ nhàng hơn khi thế giới chắc chắn sẽ đổi thay quanh họ."],"vocabulary":[{"word":"front-loaded","ipa":"/ˌfrʌnt ˈloʊdɪd/","pos":"adjective","meaning_vi":"dồn hết vào giai đoạn đầu","example":"The course is front-loaded, with most of the hard material in the first month.","example_vi":"Khóa học này dồn nặng về đầu, với phần lớn kiến thức khó nằm ở tháng đầu tiên."},{"word":"obsolete","ipa":"/ˌɑbsəˈlit/","pos":"adjective","meaning_vi":"lỗi thời","example":"Typewriters became obsolete once personal computers arrived.","example_vi":"Máy đánh chữ trở nên lỗi thời khi máy tính cá nhân xuất hiện."},{"word":"practical necessity","ipa":"/ˈpræktɪkəl nəˈsɛsəti/","pos":"noun","meaning_vi":"nhu cầu thiết thực","example":"For commuters in a big city, a motorbike is a practical necessity.","example_vi":"Với những người đi làm ở thành phố lớn, xe máy là nhu cầu thiết yếu."},{"word":"outperforms","ipa":"/ˌaʊtpərˈfɔrmz/","pos":"verb","meaning_vi":"làm tốt hơn, vượt trội hơn","example":"Steady practice usually outperforms last-minute revision.","example_vi":"Luyện tập đều đặn thường hiệu quả hơn ôn thi cấp tốc vào phút chót."},{"word":"cramming","ipa":"/ˈkræmɪŋ/","pos":"noun","meaning_vi":"học nhồi nhét","example":"Cramming the night before an exam rarely leads to lasting knowledge.","example_vi":"Học nhồi vào đêm trước kỳ thi hiếm khi để lại kiến thức lâu dài."},{"word":"atrophies","ipa":"/ˈætrəfiz/","pos":"verb","meaning_vi":"teo đi, suy yếu","example":"A skill that is never practised slowly atrophies.","example_vi":"Một kỹ năng không bao giờ được thực hành sẽ dần mai một."},{"word":"humility","ipa":"/hjuˈmɪləti/","pos":"noun","meaning_vi":"sự khiêm tốn","example":"Real expertise often comes with a surprising amount of humility.","example_vi":"Chuyên môn thực thụ thường đi kèm một sự khiêm tốn đáng ngạc nhiên."}],"questions":[{"question":"What does the writer say about the traditional model of education?","options":["It is more effective than ever","It no longer suits a fast-changing world","It was never widely adopted","It should be extended to adults only"],"answer_index":1,"explanation_vi":"Mô hình học trước, làm sau đang trở nên lỗi thời."},{"question":"According to the passage, what should motivate adult learners?","options":["Pressure from employers","Competition with friends","Relevance to their own lives","Formal qualifications"],"answer_index":2,"explanation_vi":"Người lớn cần động lực đến từ sự liên quan, không phải nghĩa vụ."},{"question":"What does the metaphor of curiosity as a muscle suggest?","options":["Curiosity is a natural talent","Curiosity declines with age","Curiosity needs expensive training","It grows through use and fades if neglected"],"answer_index":3,"explanation_vi":"Tò mò như cơ bắp: dùng thì mạnh lên, bỏ bê thì yếu đi."},{"question":"What does the writer see as the hardest part of learning?","options":["Being willing to start as a beginner again","Finding enough time","Paying for courses","Travelling to classes"],"answer_index":0,"explanation_vi":"Tác giả cho rằng sự khiêm tốn làm người mới lại là phần khó nhất."}]}', 'course', 1, 'c1-lifelong-learning', 'study', 40)
